CREATE TABLE `stories` (
  `id` int(10) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `category_id` int(10) UNSIGNED DEFAULT NULL,
  `story_type` enum('DISASTER','HUMAN') NOT NULL DEFAULT 'DISASTER',
  `event_date` date DEFAULT NULL,
  `year_label` varchar(30) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `district` varchar(120) DEFAULT NULL,
  `province` varchar(120) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `content` longtext NOT NULL,
  `deaths` varchar(100) DEFAULT NULL,
  `injuries` varchar(100) DEFAULT NULL,
  `magnitude` varchar(100) DEFAULT NULL,
  `impact` text DEFAULT NULL,
  `storyteller_name` varchar(190) DEFAULT NULL,
  `storyteller_role` varchar(120) DEFAULT NULL,
  `consent_note` text DEFAULT NULL,
  `sources` text DEFAULT NULL,
  `featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('DRAFT','REVIEW','PUBLISHED') NOT NULL DEFAULT 'DRAFT',
  `reviewed_at` datetime DEFAULT NULL,
  `reviewed_by` int(10) UNSIGNED DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `updated_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

