INSERT INTO `stories` (`id`, `title`, `slug`, `category_id`, `story_type`, `event_date`, `year_label`, `location`, `district`, `province`, `latitude`, `longitude`, `image_path`, `summary`, `content`, `deaths`, `injuries`, `magnitude`, `impact`, `storyteller_name`, `storyteller_role`, `consent_note`, `sources`, `featured`, `status`, `reviewed_at`, `reviewed_by`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(3, '2015 Gorkha Earthquake', '2015-gorkha-earthquake', 1, 'DISASTER', '2015-04-25', '2015', 'Gorkha / Kathmandu Valley', 'Gorkha', 'Bagmati', NULL, NULL, NULL, 'The Mw 7.8 earthquake of 25 April 2015 became one of the defining disasters of modern Nepal.', 'This starter article is intentionally concise. Editors should expand it using verified government, scientific and historical sources. The earthquake caused widespread structural damage, landslides and major heritage losses across central Nepal. A major aftershock occurred on 12 May 2015.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'about 9,000', NULL, 'Mw 7.8', NULL, NULL, NULL, NULL, NULL, 1, 'PUBLISHED', NULL, NULL, NULL, 1, '2026-09-10 03:46:18', '2026-09-10 14:23:14'),
(4, '1934 Nepal-Bihar Earthquake', '1934-nepal-bihar-earthquake', 1, 'DISASTER', '1934-01-15', '1934', 'Kathmandu Valley and eastern Nepal', NULL, NULL, NULL, NULL, NULL, 'The 1934 Nepal-Bihar earthquake caused extensive destruction across the Kathmandu Valley and remains one of the most damaging earthquakes in Nepal\'s modern history.', 'On 15 January 1934, a major earthquake struck Nepal and northern Bihar. Kathmandu, Bhaktapur and Patan suffered severe structural damage, while many settlements across the region were affected. The disaster exposed the vulnerability of historic masonry buildings and shaped later discussions about earthquake risk in the Kathmandu Valley. Published figures for deaths and damage differ between historical sources.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Estimated 8,500-10,700 in Nepal and Bihar combined', 'Widespread structural injuries reported', 'Estimated magnitude 8.0-8.4', 'Historic buildings, homes, roads and public infrastructure were heavily damaged across the affected region.', NULL, NULL, NULL, 'USGS earthquake history; National Society for Earthquake Technology-Nepal (NSET); historical government records', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(5, '1993 Central Nepal Floods', '1993-central-nepal-floods', 2, 'DISASTER', '1993-07-19', '1993', 'Central and southern Nepal', NULL, NULL, NULL, NULL, NULL, 'Exceptional monsoon rainfall in 1993 triggered destructive floods and landslides across central and southern Nepal.', 'The 1993 monsoon disaster followed intense rainfall over several days. Rivers rose rapidly, inundating settlements and damaging roads, bridges, farmland and other infrastructure. Flooding and rain-triggered landslides occurred together, making access and relief difficult. Reported losses vary by district and source.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'More than 1,000 reported', 'Thousands reported', 'Extreme monsoon rainfall', 'Homes, agricultural land, bridges, roads and communication links were damaged across multiple districts.', NULL, NULL, NULL, 'Government of Nepal disaster reports; Nepal Disaster Risk Reduction Portal; UN disaster summaries', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(6, '2014 Jure Landslide', '2014-jure-landslide', 3, 'DISASTER', '2014-08-02', '2014', 'Jure, Sindhupalchok', NULL, NULL, NULL, NULL, NULL, 'A massive landslide at Jure blocked the Sunkoshi River and created a dangerous temporary lake.', 'In August 2014, a large slope failure buried settlements and blocked the Sunkoshi River in Sindhupalchok. The landslide formed a temporary lake and raised the risk of a sudden outburst flood downstream. Emergency teams worked to lower the lake and evacuate exposed communities. The event demonstrated how landslides can become compound river disasters.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', '156 reported', 'Reported injuries and displaced residents', 'Large rock and debris slide', 'Settlements were buried, the Araniko Highway was disrupted, and the blocked river threatened downstream communities.', NULL, NULL, NULL, 'Department of Water Induced Disaster Management; Nepal government situation reports; ICIMOD', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(7, '2017 Mount Everest Avalanche', '2017-mount-everest-avalanche', 4, 'DISASTER', '2017-04-25', '2017', 'Khumbu, Solukhumbu', NULL, NULL, NULL, NULL, NULL, 'An avalanche on Mount Everest affected the climbing route during the 2017 spring expedition season.', 'Avalanches are a recurring hazard in Nepal\'s high mountain regions. In April 2017, an avalanche struck the Mount Everest climbing route and caused deaths among high-altitude workers. Snow conditions, serac collapse, weather and route exposure can combine to make rescue and evacuation extremely difficult.\n\nAvalanche risk in Nepal is concentrated in high mountain terrain where snowfall, wind loading, rapid temperature change, serac collapse and unstable slopes can release snow and ice onto climbing routes, trails and settlements. Historical reporting is often strongest for expeditions and popular trekking corridors, while losses in remote valleys may be incompletely recorded. The apparent severity of an avalanche depends on its path, timing, depth, terrain and the number of people present, so a report should separate deaths, injuries, missing people, rescues and route closures. Expedition records, local administration reports and technical snow studies provide complementary evidence.', 'Reported deaths among expedition workers', 'Not consistently reported', 'High-altitude avalanche', 'The climbing route was disrupted and expedition operations were affected during the spring season.', NULL, NULL, NULL, 'Department of Tourism, Government of Nepal; Himalayan Database; expedition safety reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(8, '2016 Tsho Rolpa Glacial Lake Risk', '2016-tsho-rolpa-glacial-lake-risk', 5, 'DISASTER', '2016-06-01', '1990s-2010s', 'Rolwaling Valley, Dolakha', NULL, NULL, NULL, NULL, NULL, 'Tsho Rolpa grew rapidly as Himalayan warming caused glacier retreat, creating one of Nepal\'s best-known glacial lake outburst flood risks.', 'Tsho Rolpa is a glacial lake in the Rolwaling Valley of Dolakha. Its growth led to long-running monitoring, engineering and community preparedness work. The lake is an important example of a hazard that develops over years rather than appearing as a single sudden event. Risk assessments and lake conditions should be checked against current technical monitoring.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'No single confirmed disaster toll for the lake risk period', 'Not applicable', 'Glacial lake outburst flood risk', 'Lake expansion threatened downstream settlements and infrastructure; mitigation included controlled drainage and early-warning planning.', NULL, NULL, NULL, 'ICIMOD; Department of Hydrology and Meteorology; Department of Water Resources and Irrigation', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(9, '2019 Lightning Outbreaks in Nepal', '2019-lightning-outbreaks-nepal', 6, 'DISASTER', '2019-04-01', '2019', 'Terai and hill districts', NULL, NULL, NULL, NULL, NULL, 'Lightning causes recurring deaths and injuries across Nepal, especially during the pre-monsoon and monsoon seasons.', 'Lightning is one of Nepal\'s frequently recurring weather hazards. Thunderstorms can affect open fields, rural homes, schools and outdoor work sites with little warning. Annual totals vary, but repeated outbreaks have caused deaths, injuries and livestock losses in several districts. Public awareness, safer shelter and reliable weather information are important risk-reduction measures.\n\nLightning is a recurring atmospheric hazard in Nepal, particularly during pre-monsoon and monsoon thunderstorms. Exposure is increased when people are working in fields, travelling on foot, gathering beneath isolated trees or using poorly protected buildings and electrical equipment. Unlike a single large disaster, the national burden is usually made up of many local incidents whose details arrive through district reporting systems at different times. A responsible historical account should therefore state whether a number is an annual total, a preliminary count or an incident-specific figure, and should give equal attention to prevention measures such as safe shelter, public warnings and school procedures.', 'Varies by outbreak and annual reporting', 'Recurring injuries reported', 'Severe convective thunderstorms', 'People, livestock, homes, electrical equipment and communications can be affected by lightning strikes and fires.', NULL, NULL, NULL, 'Department of Hydrology and Meteorology; Nepal Disaster Risk Reduction Portal; National Emergency Operation Centre', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(10, '2017 Terai Floods', '2017-terai-floods', 7, 'DISASTER', '2017-08-11', '2017', 'Terai and southern Nepal', NULL, NULL, NULL, NULL, NULL, 'Heavy monsoon storms and rainfall in August 2017 produced widespread flooding across Nepal\'s southern plains.', 'The 2017 monsoon brought intense rainfall to much of the Terai and other parts of Nepal. Floodwaters affected homes, roads, farmland, schools and health services. The disaster was linked to a wider regional monsoon event across South Asia. Relief access was complicated by damaged transport links and the large number of displaced households.\n\nSevere storms in Nepal may combine hail, damaging wind, lightning, intense short-duration rain and, in some places, flash flooding. Their impacts can be highly localized: a single storm cell may destroy crops and roofs in one municipality while nearby stations record much less severe weather. Agricultural losses are particularly difficult to compare because crop stage, protected cultivation, livestock exposure and access to insurance vary between communities. Weather-station observations, radar or satellite evidence, local damage surveys and government relief records should be considered together when reconstructing an event.', 'More than 140 reported in Nepal', 'Hundreds reported', 'Exceptional monsoon storm and rainfall', 'Large areas of agricultural land and settlements were inundated; roads, bridges and public services were disrupted.', NULL, NULL, NULL, 'Government of Nepal post-disaster needs assessment; UN OCHA situation reports; Department of Hydrology and Meteorology', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(11, '2019 Bara Tornado', '2019-bara-tornado', 8, 'DISASTER', '2019-03-31', '2019', 'Bara and Parsa', NULL, NULL, NULL, NULL, NULL, 'A rare and destructive tornado struck parts of southern Nepal in March 2019.', 'On 31 March 2019, a severe windstorm and tornado-like event affected Bara and Parsa districts. Homes were damaged or destroyed and communities reported deaths and injuries. The event drew attention to the need for stronger local severe-weather warnings and safer building practices in a country where tornadoes are uncommon but possible.\n\nTornadoes and tornado-like rotating windstorms are uncommon in Nepal but can produce concentrated destruction over a narrow path. Classification is difficult when an event has not been observed by radar or surveyed soon after the damage, because straight-line winds, downbursts and rotating storms can leave similar local evidence. A wiki-style record should identify the reporting authority, describe the affected path and avoid treating every severe wind report as a confirmed tornado. Homes, roofs, trees, crops, electricity lines and community buildings are important indicators of impact, while casualty figures should be linked to a dated official assessment.', '29 reported', 'Hundreds reported', 'Severe rotating windstorm', 'Roofs and houses were damaged, electricity and communications were interrupted, and local communities required emergency assistance.', NULL, NULL, NULL, 'Government of Nepal disaster assessment; Department of Hydrology and Meteorology; National Emergency Operation Centre', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(12, '2009 Mid-Western Nepal Drought', '2009-mid-western-nepal-drought', 9, 'DISASTER', '2009-01-01', '2008-2009', 'Mid-western and far-western Nepal', NULL, NULL, NULL, NULL, NULL, 'Poor winter rainfall contributed to drought conditions, crop losses and food insecurity in western Nepal during 2008-2009.', 'Drought in Nepal can develop when winter or monsoon rainfall is insufficient for crops, livestock and household water supplies. The 2008-2009 dry period affected farming communities in western and mid-western districts. Drought impacts are often gradual and underreported compared with sudden disasters, but they can increase food insecurity, debt and migration.\n\nDrought is a slow-onset hazard caused by a sustained mismatch between available water and the needs of people, ecosystems, crops or livestock. In Nepal it may follow deficient winter rain, a delayed or weak monsoon, prolonged dry spells, reduced spring water or a combination of these conditions. The effects are often uneven: one district may experience crop failure while another has adequate irrigation or rainfall. Historical analysis should distinguish meteorological drought from agricultural, hydrological and socioeconomic drought, and should describe food security, migration, livestock, drinking-water access and household coping strategies rather than relying only on a death toll.', 'No single disaster toll', 'Livelihood and food-security impacts reported', 'Below-normal seasonal rainfall', 'Crop production, drinking-water access and livestock conditions were affected in vulnerable rural communities.', NULL, NULL, NULL, 'FAO Nepal food security reports; Government of Nepal agricultural assessments; Department of Hydrology and Meteorology', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(13, '2021 Nepal Heat Wave', '2021-nepal-heat-wave', 10, 'DISASTER', '2021-06-01', '2021', 'Terai plains', NULL, NULL, NULL, NULL, NULL, 'Extreme pre-monsoon temperatures regularly affect Nepal\'s Terai, where heat exposure is increasing with urbanization and climate change.', 'Heat waves are a growing concern in the lowland Terai. Prolonged high temperatures can affect outdoor workers, older people, children and people with existing health conditions. The 2021 hot season illustrates the importance of heat-health warnings, drinking water, shade, changed work schedules and access to medical care. Exact impacts should be updated using official annual health and weather records.\n\nHeat waves in Nepal are most strongly associated with the Terai and southern plains, where high temperatures can combine with humidity, limited shade, outdoor labour, dense settlements and restricted access to cooling or medical care. Heat is often undercounted because illness may be recorded as dehydration, cardiovascular stress or another condition rather than as a disaster fatality. A useful historical record should include observed temperatures, duration, affected districts, vulnerable groups and public-health measures when those data are available. Heat warnings, drinking water, shaded rest, adjusted work hours and access to treatment are central parts of risk reduction.', 'Not consistently reported as a single event', 'Heat-related illness reported seasonally', 'Extreme high temperature', 'Heat stress affected health, work capacity, water demand and livestock conditions in hot lowland districts.', NULL, NULL, NULL, 'Department of Hydrology and Meteorology; Ministry of Health and Population; WHO heat-health guidance', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(14, '1998 Nepal Cold Wave', '1998-nepal-cold-wave', 11, 'DISASTER', '1998-01-01', '1998', 'Terai plains', NULL, NULL, NULL, NULL, NULL, 'Winter cold waves and persistent fog can create serious health and livelihood risks in Nepal\'s southern plains.', 'Cold waves in the Terai are associated with persistent fog, low temperatures and disruption to transport, schools, farming and daily work. Vulnerability is higher for people without adequate heating, older adults, children and low-income households. Historical reporting is uneven, so the human toll of individual cold-wave seasons should be treated cautiously.\n\nCold waves in the Terai are commonly accompanied by persistent fog, low daytime temperatures and reduced visibility. The hazard affects people living in poorly insulated homes, older adults, children, outdoor workers, people with chronic illness, livestock and winter crops. Transport and school attendance may also be disrupted even when no single dramatic incident is recorded. Because cold-related deaths and illness can be attributed to several medical causes, historical totals are frequently uncertain. Records should therefore explain the duration and geographic extent of the cold period and identify the source used for any health estimate.', 'Seasonal impacts vary by district', 'Cold-related illness reported', 'Persistent low temperature and fog', 'Health risks, transport disruption, crop stress and livestock losses were reported during severe winter conditions.', NULL, NULL, NULL, 'Department of Hydrology and Meteorology; Government of Nepal winter disaster reports; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(15, '2016 Nepal Forest Fires', '2016-nepal-forest-fires', 12, 'DISASTER', '2016-04-01', '2016', 'Hills and Terai forests', NULL, NULL, NULL, NULL, NULL, 'The dry season of 2016 saw widespread forest fires across Nepal, affecting air quality, forests and nearby communities.', 'Wildfires occur every year in Nepal, with the greatest danger often arriving before the monsoon when vegetation is dry and winds can spread flames quickly. The 2016 fire season affected forests and exposed settlements in several regions. Smoke can create health hazards far beyond the fire line, while repeated burning can damage biodiversity, soil and watersheds.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Varies by incident', 'Varies by incident', 'Widespread dry-season fires', 'Forest habitat, community assets, air quality and nearby agricultural land were affected in multiple districts.', NULL, NULL, NULL, 'Department of Forests and Soil Conservation; ICIMOD fire monitoring; NASA FIRMS fire data', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(16, '2008 Koshi Embankment Breach', '2008-koshi-embankment-breach', 13, 'DISASTER', '2008-08-18', '2008', 'Sunsari and eastern Nepal', NULL, NULL, NULL, NULL, NULL, 'The 2008 breach of the Koshi River embankment caused severe flooding and displacement in eastern Nepal.', 'In August 2008, the Koshi River changed course after an embankment breach near Kusaha in Sunsari. Flooding affected settlements, farmland, transport and cross-border communities. The event shows how natural river processes, infrastructure condition, land use and exposure can combine into a major disaster. It is included here as an example of a complex hazard that does not fit one category alone.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Reported deaths across affected areas', 'Large displaced population', 'Major river and embankment failure', 'Settlements and farmland were inundated, and many households required evacuation and longer-term resettlement support.', NULL, NULL, NULL, 'Government of Nepal flood assessments; World Bank disaster reports; ICIMOD', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:46:18', '2026-09-10 05:18:40'),
(30, '1255 Kathmandu Valley Earthquake', '1255-kathmandu-valley-earthquake', 1, 'DISASTER', '1255-06-07', '1255', 'Kathmandu Valley', NULL, NULL, NULL, NULL, NULL, 'The earliest major earthquake in Nepal for which a historical record survives.', 'On 7 June 1255 a major earthquake struck the Kathmandu Valley. Historical accounts describe severe destruction of buildings and temples and a very large loss of life. NSET identifies it as the first recorded earthquake in Nepal and reports that King Abhaya Malla died. The commonly cited magnitude of about 7.7 is a reconstruction, not an instrumental measurement.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Historical account: about one third of Kathmandu population; exact number uncertain', 'Not reliably known', 'Estimated about 7.7', 'Buildings and temples collapsed or were severely damaged; wider humanitarian hardship followed.', NULL, NULL, NULL, 'NSET chronological historical earthquake catalogue', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(31, '1260 Nepal Earthquake', '1260-nepal-earthquake', 1, 'DISASTER', '1260-01-01', '1260', 'Kathmandu Valley and surrounding areas', NULL, NULL, NULL, NULL, NULL, 'A major earthquake recorded during the Malla period caused heavy loss of life and property.', 'The 1260 earthquake is one of the earliest major earthquakes in Nepal’s surviving historical record. Contemporary information is limited. NSET records heavy loss of life and property and notes epidemic and famine in the aftermath. Exact date, magnitude and casualty figures are not reliably established.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Heavy loss of life reported; exact number unknown', 'Unknown', 'Not reliably established', 'Buildings and temples were damaged or destroyed and wider social hardship was reported.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(32, '1408 Nepal Earthquake', '1408-nepal-earthquake', 1, 'DISASTER', '1408-09-01', '1408', 'Kathmandu Valley and surrounding areas', NULL, NULL, NULL, NULL, NULL, 'A major historical earthquake caused heavy damage to temples, buildings and settlements.', 'Historical records place a major earthquake in August or September 1408. NSET records destruction of the Rato Machhindranath temple, damage to many buildings and temples, ground cracks and heavy loss of life and livestock. The exact day and scientific magnitude remain uncertain.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Heavy loss of life reported; exact number unknown', 'Unknown', 'Estimated about 7.0 in NSET historical catalogue', 'Temples, buildings, land and livestock were affected.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(33, '1681 Nepal Earthquake', '1681-nepal-earthquake', 1, 'DISASTER', '1681-12-01', '1681', 'Kathmandu Valley and Nepal', NULL, NULL, NULL, NULL, NULL, 'A major historical earthquake caused loss of life and damage to buildings and temples.', 'Historical records identify a significant earthquake around December 1681 or January 1682. Available documentation is limited, but NSET records loss of life and property and damage or destruction of buildings and temples.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Heavy loss of life reported; exact number unknown', 'Unknown', 'Not reliably established', 'Historic buildings and temples were damaged or destroyed.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(34, '1767 Nepal Earthquake Sequence', '1767-nepal-earthquake-sequence', 1, 'DISASTER', '1767-06-01', '1767', 'Nepal including Kathmandu Valley', NULL, NULL, NULL, NULL, NULL, 'A significant 1767 earthquake sequence included numerous shocks and aftershocks.', 'NSET records about 21 shocks and aftershocks within roughly 24 hours in June-July 1767. Surviving records do not support a reliable modern magnitude or casualty total.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably known', 'Not reliably known', 'Not established', 'Repeated shaking affected buildings and communities.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(35, '1810 Nepal Earthquake', '1810-nepal-earthquake', 1, 'DISASTER', '1810-05-01', '1810', 'Nepal and Kathmandu Valley', NULL, NULL, NULL, NULL, NULL, 'The 1810 earthquake caused moderate to heavy human and property losses.', 'A major earthquake was recorded in May 1810. NSET describes moderate to heavy loss of life and property. No reliable instrumental magnitude or precise casualty count exists.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Moderate to heavy loss reported; exact number unknown', 'Unknown', 'Not reliably established', 'Buildings and property were damaged.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(36, '1823 Nepal Earthquake', '1823-nepal-earthquake', 1, 'DISASTER', '1823-01-01', '1823', 'Nepal', NULL, NULL, NULL, NULL, NULL, 'A historical earthquake recorded in 1823 caused loss of life and property, although details are limited.', 'NSET records a 1823 earthquake with minor loss of life and property. Exact date, magnitude and geographic extent are uncertain.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Minor loss reported; exact number unknown', 'Unknown', 'Not established', 'Localized building and property damage was reported.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(37, '1833 Nepal Earthquake', '1833-nepal-earthquake', 1, 'DISASTER', '1833-08-26', '1833', 'Kathmandu Valley and central Nepal', NULL, NULL, NULL, NULL, NULL, 'The 1833 earthquake sequence was one of the most important pre-instrumental earthquakes in the Kathmandu Valley.', 'On 26 August 1833 a major earthquake sequence affected Kathmandu and surrounding regions. Historical accounts describe repeated strong shocks and substantial damage. NSET records 18,000 buildings and temples damaged in the broader sequence record. Another strong earthquake occurred on 25 September, with additional shocks in 1834. Modern magnitude estimates are reconstructed and vary.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Casualty estimates vary; no single authoritative total', 'Not reliably established', 'Historical estimates vary', 'About 18,000 buildings and temples were reported damaged in the NSET record.', NULL, NULL, NULL, 'NSET historical earthquake catalogue; historical and paleoseismic research', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(38, '1834 Nepal Earthquake Sequence', '1834-nepal-earthquake-sequence', 1, 'DISASTER', '1834-07-11', '1834', 'Kathmandu Valley and Nepal', NULL, NULL, NULL, NULL, NULL, 'Several strong shocks were recorded in 1834 following the destructive 1833 sequence.', 'Historical records list strong shocks on 11 July, 13 July and 26 September 1834, along with other tremors. NSET describes heavy loss of life and property.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Heavy loss reported; exact number unknown', 'Unknown', 'Not reliably established', 'Repeated earthquakes caused additional structural damage and prolonged disruption.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(39, '1980 Bajhang Earthquake', '1980-bajhang-earthquake', 1, 'DISASTER', '1980-08-04', '1980', 'Bajhang, western Nepal', NULL, NULL, NULL, NULL, NULL, 'The 1980 Bajhang earthquake killed and injured hundreds and damaged thousands of buildings.', 'NSET records a magnitude of about 6.1, 46 deaths and 236 injuries. It also records 12,817 buildings/temples collapsed and 13,298 damaged.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', '46', '236', 'About 6.1', 'Thousands of rural buildings were collapsed or damaged.', NULL, NULL, NULL, 'NSET historical earthquake catalogue', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(40, '1988 Udayapur Earthquake', '1988-udayapur-earthquake', 1, 'DISASTER', '1988-08-21', '1988', 'Udayapur and eastern Nepal', NULL, NULL, NULL, NULL, NULL, 'The 1988 Udayapur earthquake caused widespread damage and hundreds of deaths in eastern Nepal.', 'On 21 August 1988 a major earthquake struck eastern Nepal. Historical Nepal earthquake records commonly report about 721 deaths and magnitude estimates around 6.5. Homes and public buildings were damaged and landslides occurred in affected areas.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'About 721 reported', 'Hundreds reported', 'About 6.5', 'Homes, schools and other structures were damaged across eastern Nepal.', NULL, NULL, NULL, 'NSET earthquake catalogue; Government of Nepal; USGS', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(41, '2011 Sikkim Earthquake and Nepal Impacts', '2011-sikkim-earthquake-nepal', 1, 'DISASTER', '2011-09-18', '2011', 'Eastern Nepal and Sikkim region', NULL, NULL, NULL, NULL, NULL, 'The 2011 Sikkim earthquake was strongly felt across eastern Nepal.', 'On 18 September 2011 a magnitude 6.9 earthquake struck the Sikkim region. Strong shaking was experienced in eastern Nepal and landslides and localized structural damage occurred. It is best described as a regional earthquake with impacts in Nepal.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Nepal-only total varies by source', 'Reported injuries', 'Mw 6.9', 'Localized structural damage and landslides affected eastern Nepal.', NULL, NULL, NULL, 'USGS; Government of Nepal disaster reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(42, '2023 Jajarkot Earthquake', '2023-jajarkot-earthquake', 1, 'DISASTER', '2023-11-03', '2023', 'Jajarkot and Rukum West, Karnali Province', NULL, NULL, NULL, NULL, NULL, 'The 2023 Jajarkot earthquake caused major casualties and housing destruction in western Nepal.', 'On 3 November 2023 a magnitude 5.7 earthquake struck western Nepal. Jajarkot and Rukum West suffered severe damage, especially where vulnerable homes could not withstand shaking. Official post-event assessments recorded 154 deaths and hundreds of injuries, with tens of thousands of houses damaged.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', '154', 'Hundreds', 'Magnitude 5.7', 'Homes collapsed or were damaged and essential services were disrupted.', NULL, NULL, NULL, 'USGS; Government of Nepal/NDRRMA post-earthquake assessments', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(43, '1978 Tinau Basin Flood', '1978-tinau-basin-flood', 2, 'DISASTER', '1978-07-01', '1978', 'Tinau Basin and southern Nepal', NULL, NULL, NULL, NULL, NULL, 'A major Tinau Basin flood is listed among Nepal’s historical flood disasters.', 'The 1978 Tinau Basin flood followed intense monsoon rainfall and caused damage along the river system. Nepal government disaster-risk records identify it as a major historical flood. Older reporting is incomplete, so unsupported precise casualty totals are not given here.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'Settlements, farmland and infrastructure were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(44, '1980 Koshi Flood', '1980-koshi-flood', 2, 'DISASTER', '1980-07-01', '1980', 'Koshi Basin, eastern Nepal', NULL, NULL, NULL, NULL, NULL, 'A major Koshi flood in 1980 is recorded among Nepal’s important historical floods.', 'The Koshi is highly exposed to monsoon flooding because of its huge catchment, steep terrain, sediment loads and dense downstream settlement. The 1980 flood is listed in Nepal government historical disaster records, although exact casualty and economic-loss figures are not consistently reported in surviving summaries.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'Settlements, farmland and infrastructure in the Koshi basin were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40');
INSERT INTO `stories` (`id`, `title`, `slug`, `category_id`, `story_type`, `event_date`, `year_label`, `location`, `district`, `province`, `latitude`, `longitude`, `image_path`, `summary`, `content`, `deaths`, `injuries`, `magnitude`, `impact`, `storyteller_name`, `storyteller_role`, `consent_note`, `sources`, `featured`, `status`, `reviewed_at`, `reviewed_by`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(45, '1985 Tadi River Basin Flood', '1985-tadi-river-basin-flood', 2, 'DISASTER', '1985-07-01', '1985', 'Tadi River Basin', NULL, NULL, NULL, NULL, NULL, 'The 1985 Tadi basin flood is recorded among Nepal’s major historical flood disasters.', 'Heavy monsoon rainfall produced destructive flooding in the Tadi River basin in 1985. Exact casualty and economic-loss figures are not consistently available in national historical summaries.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'Settlements, agricultural land and river infrastructure were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(46, '1987 Sunkoshi Basin Flood', '1987-sunkoshi-basin-flood', 2, 'DISASTER', '1987-07-01', '1987', 'Sunkoshi Basin', NULL, NULL, NULL, NULL, NULL, 'The 1987 Sunkoshi basin flood is included in Nepal’s historical flood record.', 'The Sunkoshi is vulnerable to flash floods, landslides and debris flows. A major flood in 1987 is listed among the historical flood disasters recorded by Nepal authorities. Precise casualty figures are not consistently available in the national historical summaries.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'River corridors, settlements, agriculture and transport infrastructure were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(47, '1993 Central Nepal Flood and Landslide Disaster', '1993-central-nepal-flood-landslide-disaster', 2, 'DISASTER', '1993-07-19', '1993', 'Central and southern Nepal', NULL, NULL, NULL, NULL, NULL, 'Exceptional monsoon rainfall produced catastrophic floods and landslides across central and southern Nepal.', 'In July 1993 exceptionally heavy monsoon rainfall triggered widespread floods, flash floods and landslides. Government disaster-risk summaries report more than 1,000 deaths in the event period. Because floods and landslides occurred simultaneously across many districts, totals differ by reporting boundary.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'More than 1,000 in national summaries', 'Thousands reported/affected', 'Exceptional monsoon rainfall', 'Roads, bridges, homes, agricultural land and communication links were severely damaged.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal; UN disaster summaries', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(48, '2008 Koshi Flood and Embankment Breach', '2008-koshi-flood-embankment-breach', 2, 'DISASTER', '2008-08-18', '2008', 'Kusaha, Sunsari and Koshi Basin', NULL, NULL, NULL, NULL, NULL, 'The August 2008 Koshi embankment breach caused catastrophic flooding and large-scale displacement.', 'On 18 August 2008 the Koshi River breached its eastern embankment near Kusaha in Sunsari and shifted into an old channel. Floodwater inundated settlements and agricultural land in eastern Nepal and affected communities across the border in India. The event showed how river dynamics, embankment condition, sedimentation and exposure can combine into a transboundary disaster.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'More than 200 across wider affected region; totals vary', 'Large numbers injured/displaced', 'Major river and embankment failure', 'Large areas of farmland and settlements were inundated and many households required prolonged assistance.', NULL, NULL, NULL, 'Government of Nepal; World Bank; ICIMOD; UN disaster assessments', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(49, '2012 Seti River Flash Flood', '2012-seti-river-flash-flood', 2, 'DISASTER', '2012-05-05', '2012', 'Seti River, Kaski and Pokhara area', NULL, NULL, NULL, NULL, NULL, 'A sudden destructive flood/debris-flow event on the Seti River caused major loss of life near Pokhara.', 'On 5 May 2012 a sudden surge of water and debris travelled down the Seti River near Pokhara. The event caused widespread destruction along the river corridor and killed many people. The sudden nature of the disaster highlighted the danger of high-mountain source processes and limited warning time in narrow valleys.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Dozens reported; exact totals vary', 'Reported injuries/missing', 'Sudden flash flood/debris flow', 'Settlements, bridges and riverbank infrastructure were damaged.', NULL, NULL, NULL, 'Government of Nepal disaster reports; ICIMOD and scientific studies', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(50, '2015 Earthquake-Triggered Landslides', '2015-earthquake-triggered-landslides', 3, 'DISASTER', '2015-04-25', '2015', 'Central and northern Nepal', NULL, NULL, NULL, NULL, NULL, 'The 2015 earthquake triggered thousands of landslides across the Himalayan and mid-hill regions.', 'The Mw 7.8 Gorkha earthquake destabilized slopes over a huge area. Landslides blocked roads, buried settlements, damaged trekking routes and isolated mountain communities. Major slope failures and rock avalanches occurred around Langtang. Monsoon rainfall later reactivated unstable slopes.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Included within overall earthquake toll; separate total varies', 'Included within overall earthquake totals', 'Earthquake-triggered slope failures', 'Roads, trails, villages and rivers were affected and some slopes remained unstable for years.', NULL, NULL, NULL, 'USGS; ICIMOD; Government of Nepal; peer-reviewed research', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(51, '2017 Terai Monsoon Floods', '2017-terai-monsoon-floods', 2, 'DISASTER', '2017-08-11', '2017', 'Terai and southern Nepal', NULL, NULL, NULL, NULL, NULL, 'Exceptional monsoon rainfall in August 2017 caused widespread flooding across southern Nepal.', 'The 2017 monsoon brought intense rainfall to the Terai and other parts of Nepal. The World Bank estimated about 1.7 million people were affected and damages and losses were around US$585 million. Homes, farmland, roads, bridges, schools and health facilities were affected.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'More than 140 reported in Nepal', 'Hundreds reported', 'Exceptional monsoon rainfall', 'Large areas of farmland and settlements were inundated and transport, health and education services were disrupted.', NULL, NULL, NULL, 'Government of Nepal Post Disaster Needs Assessment; World Bank; UN OCHA; DHM', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(52, '2021 Melamchi Flood and Debris Flow', '2021-melamchi-flood-debris-flow', 2, 'DISASTER', '2021-06-15', '2021', 'Melamchi and Helambu, Sindhupalchok', NULL, NULL, NULL, NULL, NULL, 'A catastrophic flood and debris-flow event struck the Melamchi and Helambu valleys.', 'On 15 June 2021 an extreme flood and debris-flow event struck Melamchi and Helambu. ICIMOD reported five deaths and 20 people missing in its immediate assessment. Homes, bridges, roads, hydropower facilities and the Melamchi Water Supply Project were damaged.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', '5 deaths; 20 missing in immediate ICIMOD assessment', 'Not consistently reported', 'Extreme flood/debris flow', 'Bridges, roads, homes, hydropower and water-supply infrastructure were damaged.', NULL, NULL, NULL, 'ICIMOD; Government of Nepal; NDRRMA', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(53, '2021 October Floods and Landslides', '2021-october-floods-landslides', 2, 'DISASTER', '2021-10-18', '2021', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Unusually heavy post-monsoon rainfall caused widespread floods and landslides in October 2021.', 'In October 2021 unusually heavy rainfall after the normal monsoon caused floods and landslides across many parts of Nepal. The timing made the event particularly disruptive. Government reporting recorded substantial deaths, infrastructure losses and agricultural damage, with totals varying by reporting cut-off.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Dozens reported; final total depends on reporting period', 'Many reported injuries', 'Extreme post-monsoon rainfall', 'Roads, bridges, homes, crops and services were damaged.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; UN situation reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(54, '2024 Nepal Monsoon Floods and Landslides', '2024-nepal-monsoon-floods-landslides', 2, 'DISASTER', '2024-09-27', '2024', 'Central and eastern Nepal including Kathmandu region', NULL, NULL, NULL, NULL, NULL, 'Extreme late-September rainfall caused severe floods and landslides across Nepal.', 'In late September 2024 exceptionally heavy rainfall caused severe flooding and landslides in multiple parts of Nepal. Kathmandu Valley and surrounding districts were among the hardest-hit areas. Roads, bridges, homes and public infrastructure suffered major damage. Final figures should follow the Government of Nepal’s consolidated assessment rather than early provisional media counts.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Official totals vary by assessment date', 'Hundreds reported in the wider disaster period', 'Extreme rainfall and river flooding', 'Homes, roads, bridges, agricultural land and public infrastructure were damaged.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; UN and World Bank assessments', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(55, '1981 Zhangzangbo Glacial Lake Outburst Flood', '1981-zhangzangbo-glof', 5, 'DISASTER', '1981-07-11', '1981', 'Zhangzangbo Valley and Sun Koshi River', NULL, NULL, NULL, NULL, NULL, 'The 1981 Zhangzangbo GLOF released an enormous volume of water and caused major damage along the Sun Koshi corridor.', 'On 11 July 1981 the Zhangzangbo/Cirenmaco GLOF released an estimated 19 million cubic metres of water in about one hour. ICIMOD reports five deaths in Nepal and hundreds injured. The flood destroyed the Friendship Bridge, damaged the Sun Koshi hydropower system and severely affected sections of the Arniko Highway.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', '5 reported in Nepal', 'Hundreds reported', 'GLOF; about 19 million m3 released in about one hour', 'Bridge, hydropower and highway infrastructure were severely damaged and trade and transport were disrupted.', NULL, NULL, NULL, 'ICIMOD; historical GLOF inventories; Nepal government technical reports', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(56, '1985 Dig Tsho Glacial Lake Outburst Flood', '1985-dig-tsho-glof', 5, 'DISASTER', '1985-08-04', '1985', 'Dig Tsho, Khumbu, Solukhumbu', NULL, NULL, NULL, NULL, NULL, 'The 1985 Dig Tsho GLOF destroyed a hydropower plant and infrastructure downstream.', 'On 4 August 1985 a GLOF from Dig Tsho sent a destructive surge down the Dudh Koshi system. ICIMOD records destruction of the nearly completed Namche hydropower plant, bridges, trails and cultivated land and loss of life.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Lives lost; exact total varies', 'Not consistently reported', 'GLOF', 'Namche hydropower, bridges, trails and agricultural land were damaged or destroyed.', NULL, NULL, NULL, 'ICIMOD GLOF inventories; Nepal government technical reports', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(57, '1991 Chubung Glacial Lake Outburst Flood', '1991-chubung-glof', 5, 'DISASTER', '1991-01-01', '1991', 'Khumbu/Rolwaling region', NULL, NULL, NULL, NULL, NULL, 'A Chubung GLOF is included in historical inventories of GLOFs affecting Nepal.', 'The 1991 Chubung event is documented in Himalayan GLOF inventories. The public record is less detailed than for the 1981 and 1985 events, so this article deliberately avoids unsupported precise casualty and damage numbers.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Not reliably established', 'Not reliably established', 'GLOF', 'Downstream channels and infrastructure were affected; detailed loss estimates are limited.', NULL, NULL, NULL, 'ICIMOD historical GLOF inventory', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(58, '1998 Tam Pokhari Glacial Lake Outburst Flood', '1998-tam-pokhari-glof', 5, 'DISASTER', '1998-09-03', '1998', 'Tam Pokhari, Inkhu Khola, Solukhumbu', NULL, NULL, NULL, NULL, NULL, 'An ice avalanche entered Tam Pokhari and triggered a destructive GLOF.', 'On 3 September 1998 an ice avalanche entered Tam Pokhari and generated a wave that breached the moraine dam. ICIMOD reports approximately NPR 156 million in damage and that lives were lost.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Some lives lost; exact total varies', 'Not consistently reported', 'GLOF triggered by ice avalanche', 'Downstream infrastructure and settlements were damaged.', NULL, NULL, NULL, 'ICIMOD; historical GLOF research', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(59, '2017 Langmale Glacial Lake Outburst Flood', '2017-langmale-glof', 5, 'DISASTER', '2017-05-18', '2017', 'Barun Valley, Makalu region', NULL, NULL, NULL, NULL, NULL, 'A GLOF affected the Barun Valley in eastern Nepal in 2017.', 'The Langmale GLOF occurred in the Barun Valley in 2017. It affected the high-mountain river system and demonstrated how changing glaciers and lakes can create sudden downstream hazards. Detailed event-level casualty and loss records are limited.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'No confirmed major loss of life established in sources used', 'Not consistently reported', 'GLOF', 'High-mountain river channels and infrastructure were affected.', NULL, NULL, NULL, 'ICIMOD; Himalayan cryosphere and GLOF studies', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(60, '2024 Thame Glacial Lake Outburst Flood', '2024-thame-glof', 5, 'DISASTER', '2024-08-16', '2024', 'Thame, Solukhumbu', NULL, NULL, NULL, NULL, NULL, 'A GLOF swept through Thame after the breach of glacial lakes upstream.', 'On 16 August 2024 a GLOF struck Thame. ICIMOD initially identified Thyanbo glacial lake as the source; a later NDRRMA-ICIMOD investigation described successive breaching of Upper and Lower Ngole Cho lakes about 10 km upstream. The flood destroyed or damaged homes, a school, a health post, hotels, bridges and other infrastructure and displaced residents.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'No major confirmed loss of life in initial ICIMOD assessment', 'Not consistently reported', 'Glacial lake outburst flood', 'Initial ICIMOD assessment documented 14 destroyed properties; later assessment reported widespread damage and displacement of 135 people.', NULL, NULL, NULL, 'ICIMOD; NDRRMA; DHM; ICIMOD 2025 Thame Valley GLOF study', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(61, '2014 Annapurna Snowstorm and Avalanche Disaster', '2014-annapurna-snowstorm', 4, 'DISASTER', '2014-10-14', '2014', 'Annapurna Circuit, Manang and Mustang', NULL, NULL, NULL, NULL, NULL, 'A severe October 2014 snowstorm and associated avalanches struck trekkers and mountain communities.', 'In October 2014 a severe snowstorm associated with Cyclone Hudhud produced heavy snow and blizzard conditions on the Annapurna Circuit. Trekkers and local people were caught in rapidly changing conditions, with avalanches and exposure contributing to deaths.\n\nAvalanche risk in Nepal is concentrated in high mountain terrain where snowfall, wind loading, rapid temperature change, serac collapse and unstable slopes can release snow and ice onto climbing routes, trails and settlements. Historical reporting is often strongest for expeditions and popular trekking corridors, while losses in remote valleys may be incompletely recorded. The apparent severity of an avalanche depends on its path, timing, depth, terrain and the number of people present, so a report should separate deaths, injuries, missing people, rescues and route closures. Expedition records, local administration reports and technical snow studies provide complementary evidence.', 'At least 43 reported', 'Many injured/rescued', 'Severe snowstorm and avalanche conditions', 'Trekkers died or required rescue; high passes and trails became dangerous.', NULL, NULL, NULL, 'Government of Nepal Ministry of Culture, Tourism and Civil Aviation; Himalayan rescue records; scientific studies', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(62, '2019 Bara-Parsa Tornado', '2019-bara-parsa-tornado', 8, 'DISASTER', '2019-03-31', '2019', 'Bara and Parsa', NULL, NULL, NULL, NULL, NULL, 'A rare violent tornado struck southern Nepal on 31 March 2019.', 'A severe convective storm produced a destructive tornado in Bara and Parsa. Homes were damaged or destroyed and the event caused deaths and hundreds of injuries. The disaster demonstrated the need for severe-weather observation, public warnings and safer construction in the Terai.\n\nTornadoes and tornado-like rotating windstorms are uncommon in Nepal but can produce concentrated destruction over a narrow path. Classification is difficult when an event has not been observed by radar or surveyed soon after the damage, because straight-line winds, downbursts and rotating storms can leave similar local evidence. A wiki-style record should identify the reporting authority, describe the affected path and avoid treating every severe wind report as a confirmed tornado. Homes, roofs, trees, crops, electricity lines and community buildings are important indicators of impact, while casualty figures should be linked to a dated official assessment.', '29', 'Hundreds', 'Tornado/severe rotating convective storm', 'Homes, roofs, electricity and local infrastructure were heavily damaged.', NULL, NULL, NULL, 'Government of Nepal disaster assessment; DHM; NDRRMA; meteorological studies', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(63, '2016 Nepal Wildfire Season', '2016-nepal-wildfire-season', 12, 'DISASTER', '2016-04-01', '2016', 'Multiple districts across Nepal', NULL, NULL, NULL, NULL, NULL, 'The 2016 dry-season wildfire period was a notable wildfire season affecting forests, air quality and communities.', 'Nepal experiences recurring dry-season forest fires before the summer monsoon. The 2016 season affected forests in numerous districts. Fire danger is influenced by dry vegetation, rainfall deficits, wind and human ignition. Satellite fire monitoring has become an important part of national wildfire observation.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Varies by incident', 'Varies by incident', 'Widespread dry-season wildfire activity', 'Forest ecosystems, air quality, biodiversity, agricultural land and nearby settlements were affected.', NULL, NULL, NULL, 'Department of Forests and Soil Conservation; ICIMOD; NASA FIRMS', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(64, '2021 Nepal Wildfire Season', '2021-nepal-wildfire-season', 12, 'DISASTER', '2021-03-01', '2021', 'Multiple districts across Nepal', NULL, NULL, NULL, NULL, NULL, 'Nepal experienced widespread wildfire activity in the dry season of 2021, with extensive smoke and air-quality impacts.', 'The dry season of 2021 produced widespread wildfire activity across Nepal. Satellite monitoring showed extensive fire activity and smoke affected populated areas during periods of poor atmospheric dispersion. The season illustrates how dry conditions, vegetation, wind and human ignition can combine into national-scale wildfire and air-quality problems.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Multiple deaths reported across incidents; no single wildfire toll', 'Multiple injuries reported across incidents', 'Widespread wildfire activity', 'Forests and biodiversity were damaged and smoke affected air quality over broad areas.', NULL, NULL, NULL, 'ICIMOD; NASA FIRMS; Government of Nepal forest and disaster reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(65, 'Major Nepal Lightning Hazard', 'major-nepal-lightning-hazard', 6, 'DISASTER', '2019-04-01', 'Recent decades', 'Terai, hills and mountain districts', NULL, NULL, NULL, NULL, NULL, 'Lightning is a recurring high-fatality hazard in Nepal, especially during pre-monsoon and monsoon seasons.', 'Lightning strikes frequently occur during Nepal’s convective storm seasons. People working in agriculture, walking outdoors or sheltering under isolated trees are particularly vulnerable. Government disaster statistics show repeated deaths and injuries across Nepal. This article is a hazard-history entry; individual incidents should be added as separate records when available.\n\nLightning is a recurring atmospheric hazard in Nepal, particularly during pre-monsoon and monsoon thunderstorms. Exposure is increased when people are working in fields, travelling on foot, gathering beneath isolated trees or using poorly protected buildings and electrical equipment. Unlike a single large disaster, the national burden is usually made up of many local incidents whose details arrive through district reporting systems at different times. A responsible historical account should therefore state whether a number is an annual total, a preliminary count or an incident-specific figure, and should give equal attention to prevention measures such as safe shelter, public warnings and school procedures.', 'Annual totals vary; use government incident records', 'Annual totals vary', 'Severe convective thunderstorms', 'Deaths, injuries, livestock losses, fires and electrical damage occur every year.', NULL, NULL, NULL, 'Department of Hydrology and Meteorology; Nepal Disaster Risk Reduction Portal; Ministry of Home Affairs statistics', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(66, 'Major Nepal Hailstorm and Windstorm Hazard', 'major-nepal-hailstorm-windstorm-hazard', 7, 'DISASTER', '2019-01-01', 'Recent decades', 'Terai, hills and mountain districts', NULL, NULL, NULL, NULL, NULL, 'Hailstorms, damaging winds and severe thunderstorms are recurring hazards across Nepal.', 'Severe thunderstorms can produce hail, strong winds, lightning and intense short-duration rainfall. These events damage crops, roofs, greenhouses, electricity infrastructure and communications. Agriculture is especially vulnerable because a localized hailstorm can destroy seasonal crops rapidly.\n\nSevere storms in Nepal may combine hail, damaging wind, lightning, intense short-duration rain and, in some places, flash flooding. Their impacts can be highly localized: a single storm cell may destroy crops and roofs in one municipality while nearby stations record much less severe weather. Agricultural losses are particularly difficult to compare because crop stage, protected cultivation, livestock exposure and access to insurance vary between communities. Weather-station observations, radar or satellite evidence, local damage surveys and government relief records should be considered together when reconstructing an event.', 'Varies by event', 'Varies by event', 'Severe thunderstorm, hail and wind', 'Agriculture, roofs, power lines and local infrastructure can be damaged.', NULL, NULL, NULL, 'Department of Hydrology and Meteorology; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(67, 'Nepal Drought and Dry-Season Risk', 'nepal-drought-history-and-risk', 9, 'DISASTER', '2009-01-01', '2008-2009', 'Western, mid-western and far-western Nepal', NULL, NULL, NULL, NULL, NULL, 'Drought often develops gradually through deficient winter or monsoon rainfall and produces agricultural and water-security impacts.', 'Drought develops over weeks or months rather than as a single sudden event. Nepal has experienced recurring agricultural drought, particularly when winter or monsoon rainfall is deficient. Western and mid-western farming communities can be especially vulnerable. Impacts include reduced crop yields, livestock stress, drinking-water shortages and food-security pressure.\n\nDrought is a slow-onset hazard caused by a sustained mismatch between available water and the needs of people, ecosystems, crops or livestock. In Nepal it may follow deficient winter rain, a delayed or weak monsoon, prolonged dry spells, reduced spring water or a combination of these conditions. The effects are often uneven: one district may experience crop failure while another has adequate irrigation or rainfall. Historical analysis should distinguish meteorological drought from agricultural, hydrological and socioeconomic drought, and should describe food security, migration, livestock, drinking-water access and household coping strategies rather than relying only on a death toll.', 'No single disaster death toll', 'Livelihood and food-security impacts', 'Seasonal rainfall deficit', 'Agriculture, livestock, drinking water and rural livelihoods can be affected.', NULL, NULL, NULL, 'DHM; Ministry of Agriculture and Livestock Development; FAO; Government of Nepal assessments', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(68, 'Nepal Terai Heat Wave Hazard', 'nepal-terai-heat-wave-hazard', 10, 'DISASTER', '2024-05-01', 'Recent decades', 'Terai and southern plains', NULL, NULL, NULL, NULL, NULL, 'Extreme heat is an important and increasingly concerning hazard in Nepal’s Terai.', 'The Terai regularly experiences very high temperatures during late spring and early summer. Heat risk is increased by humidity, urbanization, limited shade, outdoor work and inadequate access to cooling and drinking water. Heat waves are not always recorded as discrete disasters with reliable national mortality figures, so individual episodes should be linked to official weather and health records.\n\nHeat waves in Nepal are most strongly associated with the Terai and southern plains, where high temperatures can combine with humidity, limited shade, outdoor labour, dense settlements and restricted access to cooling or medical care. Heat is often undercounted because illness may be recorded as dehydration, cardiovascular stress or another condition rather than as a disaster fatality. A useful historical record should include observed temperatures, duration, affected districts, vulnerable groups and public-health measures when those data are available. Heat warnings, drinking water, shaded rest, adjusted work hours and access to treatment are central parts of risk reduction.', 'Event-specific mortality varies', 'Heat-related illness varies', 'Extreme high temperature', 'Health, labor productivity, agriculture, livestock and water demand can be affected.', NULL, NULL, NULL, 'DHM; Ministry of Health and Population; WHO heat-health guidance', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(69, 'Nepal Terai Cold Wave Hazard', 'nepal-terai-cold-wave-hazard', 11, 'DISASTER', '2019-01-01', 'Recent decades', 'Terai and southern plains', NULL, NULL, NULL, NULL, NULL, 'Cold waves, dense fog and prolonged winter chill periodically affect Nepal’s Terai.', 'Winter cold waves are recurring hazards in southern Nepal. Dense fog and low temperatures affect transport, schools, agriculture and vulnerable people. Impacts are often greatest among people without adequate heating and among older adults and children.\n\nCold waves in the Terai are commonly accompanied by persistent fog, low daytime temperatures and reduced visibility. The hazard affects people living in poorly insulated homes, older adults, children, outdoor workers, people with chronic illness, livestock and winter crops. Transport and school attendance may also be disrupted even when no single dramatic incident is recorded. Because cold-related deaths and illness can be attributed to several medical causes, historical totals are frequently uncertain. Records should therefore explain the duration and geographic extent of the cold period and identify the source used for any health estimate.', 'Event-specific mortality varies', 'Cold-related illness varies', 'Low temperature and persistent fog', 'Health, transport, agriculture and livestock can be affected.', NULL, NULL, NULL, 'DHM; Government of Nepal winter disaster reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(70, '2020 Nepal Monsoon Floods and Landslides', '2020-nepal-monsoon-floods-landslides', 2, 'DISASTER', '2020-07-01', '2020', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'The 2020 monsoon produced widespread floods and landslides across Nepal.', 'During the 2020 monsoon heavy rainfall triggered floods and landslides across numerous districts. Mountain roads were repeatedly blocked, houses were damaged and agricultural land was affected. The disaster occurred during the COVID-19 pandemic, complicating evacuation and relief.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by reporting cut-off', 'Many reported', 'Monsoon flood and rainfall-triggered landslides', 'Roads, bridges, homes, farms and local infrastructure were damaged.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; UN situation reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(71, '2022 Nepal Monsoon Floods and Landslides', '2022-nepal-monsoon-floods-landslides', 2, 'DISASTER', '2022-06-01', '2022', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'The 2022 monsoon produced repeated floods and landslides across Nepal.', 'Monsoon rainfall in 2022 triggered repeated floods, landslides and road disruptions. Impacts included deaths, damaged homes, blocked highways, crop losses and disruption to local services. The season consisted of many separate incidents rather than one single disaster.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by official reporting period', 'Many reported', 'Monsoon rainfall', 'Transport, agriculture, housing and local infrastructure were repeatedly affected.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(72, '2023 Nepal Monsoon Floods and Landslides', '2023-nepal-monsoon-floods-landslides', 2, 'DISASTER', '2023-06-01', '2023', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Floods and landslides during the 2023 monsoon caused repeated casualties and infrastructure damage.', 'The 2023 monsoon produced numerous localized floods, landslides and debris flows. Mountain highways and rural roads were particularly vulnerable to slope failure, while river flooding affected settlements and agricultural land. Individual incident records are more useful than one national event total.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by official reporting period', 'Many reported', 'Monsoon rainfall', 'Roads, bridges, homes, farms and river corridors were affected.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(73, '2025 Nepal Monsoon Flood and Landslide Events', '2025-nepal-monsoon-flood-landslide-events', 2, 'DISASTER', '2025-06-01', '2025', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Nepal continued to experience recurring monsoon floods, landslides and debris flows in 2025.', 'The 2025 monsoon produced multiple localized flood and landslide disasters affecting highways, bridges, settlements, agriculture and hydropower infrastructure. Because the season consisted of many incidents, final casualty and damage totals should be taken from the consolidated Government of Nepal database.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by official reporting period', 'Many reported', 'Monsoon rainfall', 'Transport, settlements, agriculture and infrastructure were repeatedly disrupted.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40'),
(74, '2026 Rasuwa High-Mountain Flash Flood Disaster', '2026-rasuwa-high-mountain-flash-flood', 2, 'DISASTER', '2026-08-26', '2026', 'Rasuwa and northern Nepal', NULL, NULL, NULL, NULL, NULL, 'A major high-mountain flash flood struck Rasuwa in August 2026, highlighting cryosphere-linked flood and debris-flow risk.', 'On 26 August 2026 a major flash flood swept through Rasuwa district in northern Nepal. The event affected settlements and infrastructure along the mountain river corridor and raised concerns about downstream flooding. Because the disaster is recent, casualty and damage assessments can change as search-and-rescue operations and official investigations continue.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Ongoing assessment; final total not established', 'Ongoing assessment', 'High-mountain flash flood/debris-flow event', 'Roads, bridges, settlements and border-area infrastructure were affected; downstream risk required monitoring.', NULL, NULL, NULL, 'ICIMOD 26 August 2026 media advisory; Government of Nepal/NDRRMA; DHM', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 03:59:33', '2026-09-10 05:18:40');
INSERT INTO `stories` (`id`, `title`, `slug`, `category_id`, `story_type`, `event_date`, `year_label`, `location`, `district`, `province`, `latitude`, `longitude`, `image_path`, `summary`, `content`, `deaths`, `injuries`, `magnitude`, `impact`, `storyteller_name`, `storyteller_role`, `consent_note`, `sources`, `featured`, `status`, `reviewed_at`, `reviewed_by`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(78, '1987 Eastern Nepal Earthquake', '1987-eastern-nepal-earthquake', 1, 'DISASTER', '1987-01-01', '1987', 'Eastern Nepal', NULL, NULL, NULL, NULL, NULL, 'A damaging earthquake affected eastern Nepal and is included in national historical earthquake records.', 'The 1987 event affected communities in eastern Nepal, where rural masonry and unreinforced buildings were vulnerable to shaking. Historical summaries provide limited event-level detail, so this record is intentionally cautious about casualties and magnitude.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Historical earthquake; magnitude varies by catalogue', 'Local buildings and infrastructure were damaged in affected districts.', NULL, NULL, NULL, 'NSET historical earthquake catalogue; Government of Nepal records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(79, '1994 Nepal Earthquake Sequence', '1994-nepal-earthquake-sequence', 1, 'DISASTER', '1994-01-01', '1994', 'Central and western Nepal', NULL, NULL, NULL, NULL, NULL, 'A sequence of earthquakes in 1994 caused localized damage and renewed concern about Himalayan seismic risk.', 'Several moderate earthquakes were recorded in Nepal during 1994. The available public summaries do not support one definitive national casualty or damage total. Earthquake sequences can produce repeated shaking and increase the vulnerability of already damaged buildings.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Moderate earthquake sequence', 'Localized structural damage and disruption were reported in affected communities.', NULL, NULL, NULL, 'NSET earthquake catalogue; USGS earthquake records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(80, '1997 Bajura Earthquake', '1997-bajura-earthquake', 1, 'DISASTER', '1997-01-01', '1997', 'Bajura and far-western Nepal', NULL, NULL, NULL, NULL, NULL, 'A historical earthquake affected remote communities in far-western Nepal.', 'The 1997 Bajura event is recorded in historical earthquake listings for Nepal. Remoteness, difficult terrain and limited reporting capacity made contemporaneous damage assessment difficult. This entry should be expanded with district-level government records where available.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Magnitude not consistently reported', 'Rural homes, roads and local services may have been affected.', NULL, NULL, NULL, 'NSET earthquake catalogue; district administration records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(81, '2001 Nepal Himalayan Earthquake Activity', '2001-nepal-himalayan-earthquake-activity', 1, 'DISASTER', '2001-01-01', '2001', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'Earthquake activity in 2001 included moderate events felt across parts of Nepal.', 'Nepal lies along an active collision zone and experiences frequent earthquakes below the threshold of major disaster. The 2001 record illustrates the importance of maintaining monitoring and preparedness even when an individual event causes limited damage.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Moderate regional seismicity', 'Limited local effects were reported in available summaries.', NULL, NULL, NULL, 'NSET earthquake catalogue; USGS earthquake records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(82, '2005 Nepal Earthquake Events', '2005-nepal-earthquake-events', 1, 'DISASTER', '2005-01-01', '2005', 'Nepal and Himalayan region', NULL, NULL, NULL, NULL, NULL, 'Moderate earthquakes in 2005 were felt in parts of Nepal and contributed to the long record of Himalayan seismic activity.', 'The 2005 events are best understood as a group of moderate earthquakes rather than one single national disaster. Public records do not provide a consistent consolidated loss total, but the events reinforce the need for resilient construction and local preparedness.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Moderate Himalayan earthquakes', 'Localized shaking and minor damage were possible in affected areas.', NULL, NULL, NULL, 'NSET earthquake catalogue; USGS', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(83, '2007 Nepal Earthquake Events', '2007-nepal-earthquake-events', 1, 'DISASTER', '2007-01-01', '2007', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'Nepal recorded several moderate seismic events in 2007, with effects varying by location and building vulnerability.', 'The 2007 earthquake record includes felt events across the Himalayan region. Because many records combine felt reports with instrument observations, casualty and damage figures should be taken from individual event reports rather than inferred from the year alone.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Moderate seismic events', 'Localized shaking and minor structural effects were reported in some areas.', NULL, NULL, NULL, 'NSET earthquake catalogue; USGS earthquake records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(84, '2010 Nepal Earthquake Events', '2010-nepal-earthquake-events', 1, 'DISASTER', '2010-01-01', '2010', 'Nepal and adjoining Himalayan region', NULL, NULL, NULL, NULL, NULL, 'Moderate seismic events in 2010 affected parts of Nepal without a single consolidated national disaster toll.', 'The 2010 record shows how frequent smaller earthquakes form part of the background hazard in Nepal. Stronger local effects depend on depth, distance, soil conditions and construction quality.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Moderate Himalayan seismicity', 'Localized shaking was reported; no single nationwide damage estimate is used here.', NULL, NULL, NULL, 'NSET earthquake catalogue; USGS earthquake records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(85, '2014 Nepal Earthquake Events', '2014-nepal-earthquake-events', 1, 'DISASTER', '2014-01-01', '2014', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'Moderate earthquakes recorded before the 2015 disaster affected communities and provided another reminder of regional seismic exposure.', 'Nepal experienced multiple felt earthquakes in 2014. The available summaries do not support treating them as one event or assigning a combined casualty figure. They are included as a historical activity record for researchers reviewing the lead-up to 2015.\n\nEarthquakes in Nepal are associated with the ongoing collision between the Indian and Eurasian tectonic plates, which drives shortening and uplift across the Himalaya. The hazard is shaped not only by the size of an earthquake but also by depth, distance from populated places, local ground conditions, building materials and the ability of roads, hospitals and communications systems to remain operational. Historical accounts frequently use approximate dates, reconstructed magnitudes and changing administrative boundaries, while modern assessments may revise casualty and damage totals as field surveys continue. For that reason, this article should be read alongside the cited catalogue or government assessment, with estimates retained as estimates and later revisions documented rather than silently replaced.', 'Not reliably established', 'Not reliably established', 'Moderate regional earthquakes', 'Localized shaking and minor damage were reported in some locations.', NULL, NULL, NULL, 'NSET earthquake catalogue; USGS', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(86, '1984 Narayani Flood', '1984-narayani-flood', 2, 'DISASTER', '1984-07-01', '1984', 'Narayani Basin', NULL, NULL, NULL, NULL, NULL, 'A major monsoon flood affected communities and farmland in the Narayani basin.', 'The Narayani system carries water from the high Himalaya through the hills and plains. The 1984 flood is included in national historical flood records, although older summaries do not consistently report district-level casualties and losses.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'River settlements, farmland, roads and bridges were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(87, '1986 West Rapti Flood', '1986-west-rapti-flood', 2, 'DISASTER', '1986-07-01', '1986', 'West Rapti Basin', NULL, NULL, NULL, NULL, NULL, 'The West Rapti basin experienced a damaging historical monsoon flood in 1986.', 'The West Rapti is vulnerable to rapid rises after intense rainfall in its hill catchments. The 1986 flood is listed in historical disaster records, while precise event-level loss figures require verification from archival district reports.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'Homes, crops, roads and river crossings were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(88, '1989 Karnali Flood', '1989-karnali-flood', 2, 'DISASTER', '1989-07-01', '1989', 'Karnali Basin', NULL, NULL, NULL, NULL, NULL, 'A major flood in the Karnali basin affected river communities and transport links.', 'Flood risk in the Karnali combines intense monsoon rain, steep tributaries, sediment movement and exposed settlements. The 1989 event is retained as a historical basin record without unsupported precise casualty claims.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Historical totals vary', 'Not consistently documented', 'Severe monsoon flood', 'Riverbank settlements, farmland, roads and bridges were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(89, '1998 Nepal Monsoon Floods', '1998-nepal-monsoon-floods', 2, 'DISASTER', '1998-07-01', '1998', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'The 1998 monsoon produced floods and landslides in several parts of Nepal.', 'Seasonal disaster summaries identify 1998 as a year of damaging monsoon flooding. Since the season consisted of many separate incidents, a single national story can hide important district differences and should be supplemented with local records.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by source', 'Many reported', 'Heavy monsoon rainfall', 'Homes, crops, roads, bridges and river corridors were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(90, '2002 Nepal Monsoon Floods', '2002-nepal-monsoon-floods', 2, 'DISASTER', '2002-07-01', '2002', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Flooding during the 2002 monsoon damaged settlements, farms and transport infrastructure.', 'Repeated monsoon rainfall caused river flooding and localized flash floods across Nepal in 2002. The available public summaries are stronger on affected districts than on a single consolidated casualty total.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by source', 'Many reported', 'Monsoon flood and flash flood', 'Agricultural land, homes, roads and bridges were damaged.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(91, '2004 Nepal Monsoon Floods', '2004-nepal-monsoon-floods', 2, 'DISASTER', '2004-07-01', '2004', 'Terai and hill districts', NULL, NULL, NULL, NULL, NULL, 'The 2004 monsoon caused repeated river floods and local flash floods across Nepal.', 'Monsoon flooding in 2004 affected lowland river corridors and hill valleys. This record groups the season for archive navigation; individual district events should be cited separately when precise figures are required.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by source', 'Many reported', 'Heavy monsoon rainfall', 'Homes, fields, roads and local services were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(92, '2006 Nepal Monsoon Floods', '2006-nepal-monsoon-floods', 2, 'DISASTER', '2006-07-01', '2006', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Heavy monsoon rainfall in 2006 caused flooding and landslides across several regions of Nepal.', 'The 2006 season demonstrates the compound nature of monsoon disasters: river flooding in the plains occurred alongside landslides and road blockages in the hills. National totals vary with the reporting period used.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by source', 'Many reported', 'Monsoon flood and rainfall-triggered landslides', 'Transport, homes, farmland and public infrastructure were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(93, '2010 Nepal Monsoon Floods', '2010-nepal-monsoon-floods', 2, 'DISASTER', '2010-07-01', '2010', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'The 2010 monsoon brought repeated flooding and landslides to Nepal.', 'Seasonal rainfall caused river flooding, flash floods and slope failures in multiple districts. The impacts were distributed across many local events, so consolidated figures should be checked against official annual disaster reports.\n\nFlood disasters in Nepal reflect the interaction of monsoon rainfall, snowmelt, steep tributaries, sediment movement, river morphology and settlement on flood-prone land. The same weather system may produce rapid flash flooding in a mountain valley, prolonged inundation in the Terai and landslides on connecting roads. Damage is often greater where bridges, embankments, homes and public services have been built in exposed corridors or where early warning cannot reach communities in time. Event totals should identify the reporting date and distinguish deaths, missing people, displaced households, affected people and economic damage.', 'Season total varies by source', 'Many reported', 'Monsoon rainfall', 'Roads, bridges, homes, crops and local utilities were damaged.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(94, '1985 Baglung Landslide', '1985-baglung-landslide', 3, 'DISASTER', '1985-07-01', '1985', 'Baglung and western hills', NULL, NULL, NULL, NULL, NULL, 'A monsoon-triggered landslide affected settlements and transport routes in the western hills.', 'The steep slopes of western Nepal are vulnerable to landslides when prolonged rainfall saturates soil and weathered rock. The 1985 Baglung event is included in historical landslide records, while detailed casualty figures should be taken from district archives.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Historical totals vary', 'Not consistently documented', 'Rainfall-triggered landslide', 'Homes, farmland, trails and roads were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Department of Water Induced Disaster Management', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(95, '1988 Western Nepal Landslides', '1988-western-nepal-landslides', 3, 'DISASTER', '1988-07-01', '1988', 'Western and mid-western Nepal', NULL, NULL, NULL, NULL, NULL, 'Heavy monsoon rain triggered landslides across vulnerable western hill districts in 1988.', 'This seasonal record groups multiple slope failures rather than presenting them as one single slide. Terrain, road cutting, deforestation and rainfall can interact to increase landslide risk.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Season total varies by source', 'Many reported or displaced', 'Monsoon-triggered slope failures', 'Roads, homes, farms and mountain trails were damaged or blocked.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; NDRRMA; Department of Water Induced Disaster Management', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(96, '1996 Sindhupalchok Landslide Events', '1996-sindhupalchok-landslide-events', 3, 'DISASTER', '1996-07-01', '1996', 'Sindhupalchok and central hills', NULL, NULL, NULL, NULL, NULL, 'A series of rainfall-triggered landslides affected Sindhupalchok and nearby hill districts.', 'Sindhupalchok has steep terrain, active river incision and settlements along transport corridors. Historical monsoon records identify repeated landslide impacts in the area, although a single consolidated casualty count is not available for this grouped entry.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Season total varies by source', 'Not consistently documented', 'Rainfall-triggered landslides', 'Roads, homes, trails and river channels were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Department of Water Induced Disaster Management; ICIMOD', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(97, '2002 Myagdi Landslide Events', '2002-myagdi-landslide-events', 3, 'DISASTER', '2002-07-01', '2002', 'Myagdi and western hills', NULL, NULL, NULL, NULL, NULL, 'Monsoon landslides in Myagdi affected rural settlements and mountain transport routes.', 'The 2002 monsoon produced repeated slope failures in western hill districts including Myagdi. Landslide impacts are often cumulative, with roads blocked repeatedly and communities isolated for days or weeks.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Season total varies by source', 'Not consistently documented', 'Rainfall-triggered landslides', 'Rural roads, homes, fields and trails were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; NDRRMA; Department of Water Induced Disaster Management', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(98, '2018 Sunkoshi Landslide Events', '2018-sunkoshi-landslide-events', 3, 'DISASTER', '2018-07-01', '2018', 'Sindhupalchok and Sunkoshi corridor', NULL, NULL, NULL, NULL, NULL, 'Rainfall-triggered landslides repeatedly affected the Sunkoshi transport corridor in 2018.', 'The Sunkoshi corridor combines steep slopes, active rivers and major road infrastructure. Landslides during the 2018 monsoon blocked transport and raised concerns about secondary river blockage and debris-flow hazards.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Season total varies by incident', 'Not consistently documented', 'Monsoon-triggered landslides', 'Highways, settlements, river channels and local commerce were disrupted.', NULL, NULL, NULL, 'Department of Roads; NDRRMA; Department of Water Induced Disaster Management', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(99, '2020 Sindhupalchok Landslides', '2020-sindhupalchok-landslides', 3, 'DISASTER', '2020-07-09', '2020', 'Sindhupalchok', NULL, NULL, NULL, NULL, NULL, 'Severe rainfall-triggered landslides in Sindhupalchok caused deaths, displacement and major infrastructure damage.', 'During the 2020 monsoon, destructive landslides affected Sindhupalchok and nearby valleys. Several communities experienced loss of homes and road access. The event occurred in a region already exposed to earthquake-related slope instability and difficult terrain.\n\nLandslides are common across the middle hills and mountain valleys because steep terrain, fractured rock, intense rainfall and active river erosion combine with roads, settlement expansion and changing land use. A slide may begin as a shallow failure beside a road or become a large debris flow that blocks a river and threatens communities downstream. Earthquake shaking can leave slopes unstable for years, while later monsoon rain can reactivate cracks and scarps. Reliable interpretation therefore requires attention to the date of movement, the triggering process, the size of the slide, the exposed population and the quality of the source survey.', 'Multiple deaths reported; event totals vary', 'Many displaced or injured', 'Extreme rainfall and slope failure', 'Homes, roads, bridges and local services were damaged or isolated.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; ICIMOD', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(100, '1979 Annapurna Avalanche Events', '1979-annapurna-avalanche-events', 4, 'DISASTER', '1979-01-01', '1979', 'Annapurna and high mountain districts', NULL, NULL, NULL, NULL, NULL, 'Avalanches in the Annapurna region affected mountaineering routes and high-altitude communities.', 'High mountain avalanche records are incomplete for earlier decades, but the Annapurna region has long experienced avalanche danger from heavy snow, wind loading and unstable slopes. This grouped entry should be supplemented by expedition and local records.\n\nAvalanche risk in Nepal is concentrated in high mountain terrain where snowfall, wind loading, rapid temperature change, serac collapse and unstable slopes can release snow and ice onto climbing routes, trails and settlements. Historical reporting is often strongest for expeditions and popular trekking corridors, while losses in remote valleys may be incompletely recorded. The apparent severity of an avalanche depends on its path, timing, depth, terrain and the number of people present, so a report should separate deaths, injuries, missing people, rescues and route closures. Expedition records, local administration reports and technical snow studies provide complementary evidence.', 'Not reliably established', 'Not reliably established', 'High-altitude avalanche hazard', 'Expedition routes, grazing areas and mountain trails were affected.', NULL, NULL, NULL, 'Department of Tourism; Himalayan Database; historical expedition records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(101, '1989 Everest Avalanche Events', '1989-everest-avalanche-events', 4, 'DISASTER', '1989-01-01', '1989', 'Khumbu and Mount Everest region', NULL, NULL, NULL, NULL, NULL, 'Avalanche activity in the Everest region has repeatedly threatened climbers, porters and local communities.', 'The Everest region contains steep hanging glaciers, snow-loaded slopes and narrow travel corridors. Historical avalanche events before the modern reporting era are not always documented with consistent casualty figures, so this entry emphasizes the hazard context.\n\nAvalanche risk in Nepal is concentrated in high mountain terrain where snowfall, wind loading, rapid temperature change, serac collapse and unstable slopes can release snow and ice onto climbing routes, trails and settlements. Historical reporting is often strongest for expeditions and popular trekking corridors, while losses in remote valleys may be incompletely recorded. The apparent severity of an avalanche depends on its path, timing, depth, terrain and the number of people present, so a report should separate deaths, injuries, missing people, rescues and route closures. Expedition records, local administration reports and technical snow studies provide complementary evidence.', 'Not reliably established', 'Not reliably established', 'High-altitude avalanche hazard', 'Climbing routes, trails, camps and mountain livelihoods were exposed.', NULL, NULL, NULL, 'Himalayan Database; Department of Tourism; expedition safety records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(102, '2009 Annapurna Avalanche Events', '2009-annapurna-avalanche-events', 4, 'DISASTER', '2009-01-01', '2009', 'Annapurna and Mustang', NULL, NULL, NULL, NULL, NULL, 'Snowfall and avalanche conditions affected mountain routes in the Annapurna region in 2009.', 'Heavy snow, wind and rapid weather changes can create avalanche conditions on the Annapurna Circuit and adjoining valleys. Earlier event-level records are uneven, so this article should be treated as a regional hazard-history record rather than a single precisely measured disaster.\n\nAvalanche risk in Nepal is concentrated in high mountain terrain where snowfall, wind loading, rapid temperature change, serac collapse and unstable slopes can release snow and ice onto climbing routes, trails and settlements. Historical reporting is often strongest for expeditions and popular trekking corridors, while losses in remote valleys may be incompletely recorded. The apparent severity of an avalanche depends on its path, timing, depth, terrain and the number of people present, so a report should separate deaths, injuries, missing people, rescues and route closures. Expedition records, local administration reports and technical snow studies provide complementary evidence.', 'Not reliably established', 'Not reliably established', 'Snowstorm and avalanche conditions', 'Trails and high passes were closed or made hazardous; rescue access was difficult.', NULL, NULL, NULL, 'Department of Tourism; Himalayan Database; local administration records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(103, '2022 Manaslu Avalanche', '2022-manaslu-avalanche', 4, 'DISASTER', '2022-09-26', '2022', 'Manaslu, Gorkha', NULL, NULL, NULL, NULL, NULL, 'An avalanche on Manaslu affected climbers during the autumn expedition season.', 'In September 2022 an avalanche struck the Manaslu climbing area during a period of active expeditions. High-altitude avalanches can be triggered by snowfall, wind loading, serac collapse and changing temperatures. Casualty and rescue numbers should be checked against official expedition reports.\n\nAvalanche risk in Nepal is concentrated in high mountain terrain where snowfall, wind loading, rapid temperature change, serac collapse and unstable slopes can release snow and ice onto climbing routes, trails and settlements. Historical reporting is often strongest for expeditions and popular trekking corridors, while losses in remote valleys may be incompletely recorded. The apparent severity of an avalanche depends on its path, timing, depth, terrain and the number of people present, so a report should separate deaths, injuries, missing people, rescues and route closures. Expedition records, local administration reports and technical snow studies provide complementary evidence.', 'Reported deaths; final total varies by source', 'Reported injuries', 'High-altitude avalanche', 'Camps, climbing routes and expedition operations were affected.', NULL, NULL, NULL, 'Department of Tourism; Himalayan Database; expedition safety reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(104, '1977 Nepal Glacial Lake Flood Risk', '1977-nepal-glacial-lake-flood-risk', 5, 'DISASTER', '1977-01-01', '1977', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'Early inventories documented growing glacial lakes and potential outburst-flood hazards in Nepal.', 'Before detailed satellite monitoring, field teams documented glacial lakes and downstream exposure through surveys and local reports. This record represents the emergence of systematic GLOF risk awareness rather than one confirmed single-lake disaster.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Not applicable to a single event', 'Not applicable', 'Glacial lake outburst flood risk', 'Downstream valleys, bridges, trails and hydropower sites were exposed.', NULL, NULL, NULL, 'ICIMOD historical cryosphere research; Nepal technical reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(105, '1980 Nepal Himalayan GLOF Events', '1980-nepal-himalayan-glof-events', 5, 'DISASTER', '1980-01-01', '1980', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'Historical inventories identify destructive glacial lake outburst flood activity in the Nepal Himalaya around the early 1980s.', 'GLOFs can release water, ice and sediment with very little warning. Early event inventories are sometimes inconsistent in dates and names, so this grouped record avoids attributing uncertain details to a specific lake without a technical source.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Event totals vary by inventory', 'Event totals vary by inventory', 'Glacial lake outburst flood', 'River channels, settlements, trails and infrastructure can be damaged downstream.', NULL, NULL, NULL, 'ICIMOD GLOF inventory; Nepal government technical reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(106, '1994 Nepal GLOF Inventory Events', '1994-nepal-glof-inventory-events', 5, 'DISASTER', '1994-01-01', '1994', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'GLOF inventories from the 1990s documented increasing concern about rapidly changing Himalayan lakes.', 'The 1990s saw more systematic attention to glacial lakes, remote sensing and downstream exposure. Some inventory entries describe past events while others describe risk rather than confirmed outburst floods; researchers should distinguish the two when expanding this record.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Not reliably established', 'Not reliably established', 'GLOF risk and historical events', 'Downstream settlements and infrastructure were assessed for potential flood exposure.', NULL, NULL, NULL, 'ICIMOD; Department of Hydrology and Meteorology; Nepal technical studies', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(107, '2007 Nepal GLOF Monitoring Period', '2007-nepal-glof-monitoring-period', 5, 'DISASTER', '2007-01-01', '2007', 'Nepal Himalaya', NULL, NULL, NULL, NULL, NULL, 'Monitoring programs in the 2000s tracked expanding glacial lakes and potential outburst-flood hazards.', 'Remote sensing, field surveys and community observations improved knowledge of Nepal glacial lakes during the 2000s. This entry records a period of risk monitoring rather than a single flood, and it highlights why lake conditions and downstream warning systems require continuing updates.\n\nGlacial lake outburst floods, commonly abbreviated as GLOFs, occur when a moraine, ice dam or other natural barrier fails and releases stored lake water, sediment and ice into a downstream valley. In Nepal, lake growth is linked to glacier retreat, ice collapse, changing precipitation and the geometry of high mountain basins, although each lake has its own history and failure mechanisms. A GLOF can travel rapidly through narrow channels and damage bridges, hydropower, trails, farmland and settlements far below the lake. Inventory dates and lake names sometimes differ between publications, so event descriptions should distinguish confirmed outbursts from hazard assessments and possible future scenarios.', 'Not applicable to a single event', 'Not applicable', 'Glacial lake growth and outburst risk', 'Potential exposure included hydropower, bridges, trails and settlements downstream.', NULL, NULL, NULL, 'ICIMOD; DHM; Nepal glacial lake inventories', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(108, '2007 Nepal Lightning Incidents', '2007-nepal-lightning-incidents', 6, 'DISASTER', '2007-04-01', '2007', 'Terai and hill districts', NULL, NULL, NULL, NULL, NULL, 'Lightning caused recurring deaths, injuries and livestock losses during Nepal thunderstorms in 2007.', 'Lightning risk increases during pre-monsoon storms and remains high where people work outdoors or shelter under isolated trees and simple structures. Annual reporting groups many local incidents, so this entry should be paired with district-level records.\n\nLightning is a recurring atmospheric hazard in Nepal, particularly during pre-monsoon and monsoon thunderstorms. Exposure is increased when people are working in fields, travelling on foot, gathering beneath isolated trees or using poorly protected buildings and electrical equipment. Unlike a single large disaster, the national burden is usually made up of many local incidents whose details arrive through district reporting systems at different times. A responsible historical account should therefore state whether a number is an annual total, a preliminary count or an incident-specific figure, and should give equal attention to prevention measures such as safe shelter, public warnings and school procedures.', 'Annual total varies by government record', 'Annual total varies', 'Severe convective thunderstorms', 'People, livestock, homes and electrical systems were affected by strikes and related fires.', NULL, NULL, NULL, 'Ministry of Home Affairs disaster statistics; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40');
INSERT INTO `stories` (`id`, `title`, `slug`, `category_id`, `story_type`, `event_date`, `year_label`, `location`, `district`, `province`, `latitude`, `longitude`, `image_path`, `summary`, `content`, `deaths`, `injuries`, `magnitude`, `impact`, `storyteller_name`, `storyteller_role`, `consent_note`, `sources`, `featured`, `status`, `reviewed_at`, `reviewed_by`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(109, '2012 Nepal Lightning Incidents', '2012-nepal-lightning-incidents', 6, 'DISASTER', '2012-04-01', '2012', 'Terai, hills and mountain districts', NULL, NULL, NULL, NULL, NULL, 'Lightning remained a recurring deadly hazard across Nepal during the 2012 storm seasons.', 'The 2012 record illustrates that lightning disasters are distributed across many small incidents. Better public warnings, grounded shelters, safer school procedures and avoidance of open fields can reduce exposure.\n\nLightning is a recurring atmospheric hazard in Nepal, particularly during pre-monsoon and monsoon thunderstorms. Exposure is increased when people are working in fields, travelling on foot, gathering beneath isolated trees or using poorly protected buildings and electrical equipment. Unlike a single large disaster, the national burden is usually made up of many local incidents whose details arrive through district reporting systems at different times. A responsible historical account should therefore state whether a number is an annual total, a preliminary count or an incident-specific figure, and should give equal attention to prevention measures such as safe shelter, public warnings and school procedures.', 'Annual total varies by government record', 'Annual total varies', 'Severe convective thunderstorms', 'Deaths, injuries, livestock loss and structure fires were reported in separate incidents.', NULL, NULL, NULL, 'Ministry of Home Affairs disaster statistics; DHM', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(110, '2016 Nepal Lightning Incidents', '2016-nepal-lightning-incidents', 6, 'DISASTER', '2016-04-01', '2016', 'Terai and hill districts', NULL, NULL, NULL, NULL, NULL, 'Thunderstorm lightning caused repeated casualties and damage in Nepal during 2016.', 'Lightning incidents often rise during the transition into the monsoon. The hazard is difficult to localize without timely weather alerts, and household or workplace decisions made during a storm strongly influence outcomes.\n\nLightning is a recurring atmospheric hazard in Nepal, particularly during pre-monsoon and monsoon thunderstorms. Exposure is increased when people are working in fields, travelling on foot, gathering beneath isolated trees or using poorly protected buildings and electrical equipment. Unlike a single large disaster, the national burden is usually made up of many local incidents whose details arrive through district reporting systems at different times. A responsible historical account should therefore state whether a number is an annual total, a preliminary count or an incident-specific figure, and should give equal attention to prevention measures such as safe shelter, public warnings and school procedures.', 'Annual total varies by government record', 'Annual total varies', 'Severe convective thunderstorms', 'People, livestock, roofs, electrical equipment and communications were affected.', NULL, NULL, NULL, 'DHM; Ministry of Home Affairs disaster statistics; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(111, '2024 Nepal Lightning Incidents', '2024-nepal-lightning-incidents', 6, 'DISASTER', '2024-04-01', '2024', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Lightning continued to produce recurring deaths and injuries across Nepal in 2024.', 'The 2024 season included multiple lightning incidents during severe convective weather. Final annual counts should be taken from consolidated government data because early media reports can omit remote districts or later deaths.\n\nLightning is a recurring atmospheric hazard in Nepal, particularly during pre-monsoon and monsoon thunderstorms. Exposure is increased when people are working in fields, travelling on foot, gathering beneath isolated trees or using poorly protected buildings and electrical equipment. Unlike a single large disaster, the national burden is usually made up of many local incidents whose details arrive through district reporting systems at different times. A responsible historical account should therefore state whether a number is an annual total, a preliminary count or an incident-specific figure, and should give equal attention to prevention measures such as safe shelter, public warnings and school procedures.', 'Final annual total varies by reporting cut-off', 'Many reported', 'Severe convective thunderstorms', 'Communities, homes, farms, livestock and electrical systems were affected.', NULL, NULL, NULL, 'DHM; NDRRMA; Ministry of Home Affairs disaster statistics', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(112, '1990 Nepal Hailstorm Season', '1990-nepal-hailstorm-season', 7, 'DISASTER', '1990-03-01', '1990', 'Hills and Terai', NULL, NULL, NULL, NULL, NULL, 'Hailstorms and severe winds damaged crops and roofs in several parts of Nepal during the 1990 storm season.', 'Localized hailstorms can create large agricultural losses even when the affected area is small. Historical national reporting is incomplete for the 1990 season, so this entry focuses on the recurring hazard pattern rather than a single national loss figure.\n\nSevere storms in Nepal may combine hail, damaging wind, lightning, intense short-duration rain and, in some places, flash flooding. Their impacts can be highly localized: a single storm cell may destroy crops and roofs in one municipality while nearby stations record much less severe weather. Agricultural losses are particularly difficult to compare because crop stage, protected cultivation, livestock exposure and access to insurance vary between communities. Weather-station observations, radar or satellite evidence, local damage surveys and government relief records should be considered together when reconstructing an event.', 'Not reliably established', 'Not reliably established', 'Hail and severe convective wind', 'Crops, roofs, livestock shelters and local utilities were exposed.', NULL, NULL, NULL, 'DHM historical weather records; Government of Nepal disaster reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(113, '2000 Nepal Severe Windstorms', '2000-nepal-severe-windstorms', 7, 'DISASTER', '2000-04-01', '2000', 'Terai and hill districts', NULL, NULL, NULL, NULL, NULL, 'Severe windstorms and thunderstorms affected settlements and agriculture in Nepal around 2000.', 'Strong convective winds can occur before or during the monsoon and may damage roofs, trees, power lines and standing crops. The available historical summaries group incidents by district and do not provide one reliable national casualty total.\n\nSevere storms in Nepal may combine hail, damaging wind, lightning, intense short-duration rain and, in some places, flash flooding. Their impacts can be highly localized: a single storm cell may destroy crops and roofs in one municipality while nearby stations record much less severe weather. Agricultural losses are particularly difficult to compare because crop stage, protected cultivation, livestock exposure and access to insurance vary between communities. Weather-station observations, radar or satellite evidence, local damage surveys and government relief records should be considered together when reconstructing an event.', 'Incident totals vary', 'Incident totals vary', 'Severe convective windstorm', 'Roofs, trees, power lines and crops were damaged.', NULL, NULL, NULL, 'DHM; Nepal Disaster Risk Reduction Portal; district disaster records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(114, '2008 Nepal Hailstorm Events', '2008-nepal-hailstorm-events', 7, 'DISASTER', '2008-04-01', '2008', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Hailstorms during the 2008 pre-monsoon period affected crops, homes and local infrastructure.', 'Hail is a short-duration but high-impact hazard for farming communities. The 2008 incidents are grouped for archive discovery because individual district records are more precise than a single nationwide total.\n\nSevere storms in Nepal may combine hail, damaging wind, lightning, intense short-duration rain and, in some places, flash flooding. Their impacts can be highly localized: a single storm cell may destroy crops and roofs in one municipality while nearby stations record much less severe weather. Agricultural losses are particularly difficult to compare because crop stage, protected cultivation, livestock exposure and access to insurance vary between communities. Weather-station observations, radar or satellite evidence, local damage surveys and government relief records should be considered together when reconstructing an event.', 'Incident totals vary', 'Incident totals vary', 'Severe hailstorm', 'Crops, greenhouses, roofs and livestock shelters were damaged.', NULL, NULL, NULL, 'DHM; Ministry of Agriculture and Livestock Development; local administration records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(115, '2023 Nepal Severe Storms', '2023-nepal-severe-storms', 7, 'DISASTER', '2023-04-01', '2023', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Severe thunderstorms, damaging winds and hail affected Nepal during the 2023 storm seasons.', 'Storm cells can produce several hazards at once: lightning, hail, wind damage and intense short-duration rain. The 2023 record groups recurring events and should be read alongside individual incident reports and crop-loss assessments.\n\nSevere storms in Nepal may combine hail, damaging wind, lightning, intense short-duration rain and, in some places, flash flooding. Their impacts can be highly localized: a single storm cell may destroy crops and roofs in one municipality while nearby stations record much less severe weather. Agricultural losses are particularly difficult to compare because crop stage, protected cultivation, livestock exposure and access to insurance vary between communities. Weather-station observations, radar or satellite evidence, local damage surveys and government relief records should be considered together when reconstructing an event.', 'Incident totals vary', 'Incident totals vary', 'Severe thunderstorm and hail', 'Agriculture, roofs, electricity and communications were affected.', NULL, NULL, NULL, 'DHM; NDRRMA; Ministry of Agriculture and Livestock Development', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(116, '2000 Nepal Tornado-Like Wind Events', '2000-nepal-tornado-like-wind-events', 8, 'DISASTER', '2000-01-01', '2000', 'Terai plains', NULL, NULL, NULL, NULL, NULL, 'Tornado-like rotating wind events are rare in Nepal but can cause concentrated destruction when they occur.', 'Before the 2019 Bara event, many severe local windstorms were reported without the observations needed to classify them confidently as tornadoes. This record preserves the hazard history while avoiding an unsupported event count or casualty figure.\n\nTornadoes and tornado-like rotating windstorms are uncommon in Nepal but can produce concentrated destruction over a narrow path. Classification is difficult when an event has not been observed by radar or surveyed soon after the damage, because straight-line winds, downbursts and rotating storms can leave similar local evidence. A wiki-style record should identify the reporting authority, describe the affected path and avoid treating every severe wind report as a confirmed tornado. Homes, roofs, trees, crops, electricity lines and community buildings are important indicators of impact, while casualty figures should be linked to a dated official assessment.', 'Not reliably established', 'Not reliably established', 'Tornado-like severe wind; classification uncertain', 'Roofs, trees, crops and power infrastructure can be damaged along a narrow track.', NULL, NULL, NULL, 'DHM historical weather records; local administration reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(117, '2014 Nepal Severe Rotating Windstorm Reports', '2014-nepal-severe-rotating-windstorm-reports', 8, 'DISASTER', '2014-01-01', '2014', 'Southern Nepal', NULL, NULL, NULL, NULL, NULL, 'Severe rotating windstorm reports in southern Nepal predated improved public attention to the country tornado hazard.', 'Local storm reports do not always include radar or damage-path surveys, making tornado classification difficult. This record is retained as a research lead and should be updated only with verified meteorological evidence.\n\nTornadoes and tornado-like rotating windstorms are uncommon in Nepal but can produce concentrated destruction over a narrow path. Classification is difficult when an event has not been observed by radar or surveyed soon after the damage, because straight-line winds, downbursts and rotating storms can leave similar local evidence. A wiki-style record should identify the reporting authority, describe the affected path and avoid treating every severe wind report as a confirmed tornado. Homes, roofs, trees, crops, electricity lines and community buildings are important indicators of impact, while casualty figures should be linked to a dated official assessment.', 'Not reliably established', 'Not reliably established', 'Severe rotating windstorm; classification uncertain', 'Concentrated roof, crop and tree damage was reported in local storm accounts.', NULL, NULL, NULL, 'DHM; district administration records; meteorological research', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(118, '2022 Nepal Tornado-Like Storm Reports', '2022-nepal-tornado-like-storm-reports', 8, 'DISASTER', '2022-01-01', '2022', 'Terai and southern plains', NULL, NULL, NULL, NULL, NULL, 'Localized destructive windstorms in the Terai continued to show the need for better severe-weather observation.', 'Nepal has limited long-term tornado observations, so reports of rotating winds should be verified with damage surveys, radar and eyewitness evidence. This entry groups possible events rather than asserting that every report was a confirmed tornado.\n\nTornadoes and tornado-like rotating windstorms are uncommon in Nepal but can produce concentrated destruction over a narrow path. Classification is difficult when an event has not been observed by radar or surveyed soon after the damage, because straight-line winds, downbursts and rotating storms can leave similar local evidence. A wiki-style record should identify the reporting authority, describe the affected path and avoid treating every severe wind report as a confirmed tornado. Homes, roofs, trees, crops, electricity lines and community buildings are important indicators of impact, while casualty figures should be linked to a dated official assessment.', 'Not reliably established', 'Not reliably established', 'Tornado-like severe wind; classification uncertain', 'Homes, roofs, crops and local utilities were exposed.', NULL, NULL, NULL, 'DHM; NDRRMA; meteorological research', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(119, '1992 Nepal Drought Conditions', '1992-nepal-drought-conditions', 9, 'DISASTER', '1992-01-01', '1992', 'Western and mid-western Nepal', NULL, NULL, NULL, NULL, NULL, 'Rainfall deficits contributed to agricultural and water stress in parts of Nepal during the early 1990s.', 'Drought conditions are measured against local rainfall, soil moisture, water supply and crop needs. The 1992 record is best treated as a seasonal drought reference because national loss estimates and district severity classifications vary.\n\nDrought is a slow-onset hazard caused by a sustained mismatch between available water and the needs of people, ecosystems, crops or livestock. In Nepal it may follow deficient winter rain, a delayed or weak monsoon, prolonged dry spells, reduced spring water or a combination of these conditions. The effects are often uneven: one district may experience crop failure while another has adequate irrigation or rainfall. Historical analysis should distinguish meteorological drought from agricultural, hydrological and socioeconomic drought, and should describe food security, migration, livestock, drinking-water access and household coping strategies rather than relying only on a death toll.', 'No single disaster death toll', 'Livelihood and food-security impacts', 'Seasonal rainfall deficit', 'Crops, livestock, drinking water and household income were affected.', NULL, NULL, NULL, 'DHM; FAO; Ministry of Agriculture and Livestock Development', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(120, '2006 Nepal Drought Conditions', '2006-nepal-drought-conditions', 9, 'DISASTER', '2006-01-01', '2006', 'Mid-western, far-western and Terai districts', NULL, NULL, NULL, NULL, NULL, 'Rainfall irregularity and dry conditions affected farming and water access in parts of Nepal in 2006.', 'Agricultural drought can be intensified by delayed monsoon onset, winter rainfall deficits and limited irrigation. Available reports describe localized impacts rather than one nationally uniform disaster.\n\nDrought is a slow-onset hazard caused by a sustained mismatch between available water and the needs of people, ecosystems, crops or livestock. In Nepal it may follow deficient winter rain, a delayed or weak monsoon, prolonged dry spells, reduced spring water or a combination of these conditions. The effects are often uneven: one district may experience crop failure while another has adequate irrigation or rainfall. Historical analysis should distinguish meteorological drought from agricultural, hydrological and socioeconomic drought, and should describe food security, migration, livestock, drinking-water access and household coping strategies rather than relying only on a death toll.', 'No single disaster death toll', 'Livelihood and food-security impacts', 'Seasonal rainfall deficit', 'Crop yields, livestock, water sources and food security were affected in vulnerable areas.', NULL, NULL, NULL, 'DHM; FAO; Government of Nepal agricultural assessments', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(121, '2015 Nepal Drought and Water Stress', '2015-nepal-drought-and-water-stress', 9, 'DISASTER', '2015-01-01', '2015', 'Western and mid-western Nepal', NULL, NULL, NULL, NULL, NULL, 'Dry conditions and water stress affected some communities during the 2015 agricultural year.', 'Drought impacts can coexist with other disasters and are often overshadowed by sudden events. In 2015, local water availability, crop conditions and post-earthquake vulnerability varied widely by district, so this record does not assign a single national drought toll.\n\nDrought is a slow-onset hazard caused by a sustained mismatch between available water and the needs of people, ecosystems, crops or livestock. In Nepal it may follow deficient winter rain, a delayed or weak monsoon, prolonged dry spells, reduced spring water or a combination of these conditions. The effects are often uneven: one district may experience crop failure while another has adequate irrigation or rainfall. Historical analysis should distinguish meteorological drought from agricultural, hydrological and socioeconomic drought, and should describe food security, migration, livestock, drinking-water access and household coping strategies rather than relying only on a death toll.', 'No single disaster death toll', 'Livelihood and water-security impacts', 'Seasonal rainfall deficit and water stress', 'Agriculture, livestock and household water access were affected in some districts.', NULL, NULL, NULL, 'DHM; FAO; Ministry of Agriculture and Livestock Development', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(122, '2010 Terai Heat Wave', '2010-terai-heat-wave', 10, 'DISASTER', '2010-05-01', '2010', 'Terai plains', NULL, NULL, NULL, NULL, NULL, 'High temperatures in the Terai created seasonal heat stress for outdoor workers and vulnerable people.', 'The Terai can experience dangerous heat before the monsoon. Risk increases where shade, drinking water and healthcare are limited. Historical health reporting does not consistently separate heat-related illness from other causes, so no unsupported mortality figure is used here.\n\nHeat waves in Nepal are most strongly associated with the Terai and southern plains, where high temperatures can combine with humidity, limited shade, outdoor labour, dense settlements and restricted access to cooling or medical care. Heat is often undercounted because illness may be recorded as dehydration, cardiovascular stress or another condition rather than as a disaster fatality. A useful historical record should include observed temperatures, duration, affected districts, vulnerable groups and public-health measures when those data are available. Heat warnings, drinking water, shaded rest, adjusted work hours and access to treatment are central parts of risk reduction.', 'Event-specific mortality varies', 'Heat-related illness varies', 'Extreme pre-monsoon heat', 'Health, labor, livestock, crops and water demand were affected.', NULL, NULL, NULL, 'DHM; Ministry of Health and Population; WHO heat-health guidance', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(123, '2016 Nepal Heat Wave', '2016-nepal-heat-wave', 10, 'DISASTER', '2016-05-01', '2016', 'Terai and southern plains', NULL, NULL, NULL, NULL, NULL, 'A period of extreme pre-monsoon heat affected the Terai in 2016.', 'Heat waves can be intensified by humidity, dense settlements, limited shade and outdoor work. This event record should be paired with station observations and health surveillance because temperatures and impacts differed between districts.\n\nHeat waves in Nepal are most strongly associated with the Terai and southern plains, where high temperatures can combine with humidity, limited shade, outdoor labour, dense settlements and restricted access to cooling or medical care. Heat is often undercounted because illness may be recorded as dehydration, cardiovascular stress or another condition rather than as a disaster fatality. A useful historical record should include observed temperatures, duration, affected districts, vulnerable groups and public-health measures when those data are available. Heat warnings, drinking water, shaded rest, adjusted work hours and access to treatment are central parts of risk reduction.', 'Event-specific mortality varies', 'Heat-related illness varies', 'Extreme high temperature', 'People, livestock, crops and water systems were exposed to heat stress.', NULL, NULL, NULL, 'DHM; Ministry of Health and Population; WHO heat-health guidance', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(124, '2022 Nepal Heat Wave', '2022-nepal-heat-wave', 10, 'DISASTER', '2022-05-01', '2022', 'Terai plains', NULL, NULL, NULL, NULL, NULL, 'High temperatures and delayed monsoon conditions created heat stress across parts of the Terai in 2022.', 'The 2022 heat period shows why heat preparedness needs clear thresholds, public messaging and protection for outdoor workers. Official impact estimates should be preferred over social-media or media-only counts.\n\nHeat waves in Nepal are most strongly associated with the Terai and southern plains, where high temperatures can combine with humidity, limited shade, outdoor labour, dense settlements and restricted access to cooling or medical care. Heat is often undercounted because illness may be recorded as dehydration, cardiovascular stress or another condition rather than as a disaster fatality. A useful historical record should include observed temperatures, duration, affected districts, vulnerable groups and public-health measures when those data are available. Heat warnings, drinking water, shaded rest, adjusted work hours and access to treatment are central parts of risk reduction.', 'Event-specific mortality varies', 'Heat-related illness varies', 'Extreme high temperature', 'Health, labor productivity, agriculture, livestock and water demand were affected.', NULL, NULL, NULL, 'DHM; Ministry of Health and Population; WHO heat-health guidance', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(125, '2003 Nepal Cold Wave', '2003-nepal-cold-wave', 11, 'DISASTER', '2003-01-01', '2003', 'Terai plains', NULL, NULL, NULL, NULL, NULL, 'Persistent winter fog and low temperatures affected vulnerable communities in the Terai during 2003.', 'Cold waves are often undercounted because they develop over several days and their health impacts may be recorded under broader winter illness categories. This record groups the hazard period without claiming a precise national death toll.\n\nCold waves in the Terai are commonly accompanied by persistent fog, low daytime temperatures and reduced visibility. The hazard affects people living in poorly insulated homes, older adults, children, outdoor workers, people with chronic illness, livestock and winter crops. Transport and school attendance may also be disrupted even when no single dramatic incident is recorded. Because cold-related deaths and illness can be attributed to several medical causes, historical totals are frequently uncertain. Records should therefore explain the duration and geographic extent of the cold period and identify the source used for any health estimate.', 'Event-specific mortality varies', 'Cold-related illness varies', 'Low temperature and persistent fog', 'Health, transport, crops, livestock and schools were affected.', NULL, NULL, NULL, 'DHM; Ministry of Health and Population; Government of Nepal winter reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(126, '2011 Nepal Cold Wave', '2011-nepal-cold-wave', 11, 'DISASTER', '2011-01-01', '2011', 'Terai and southern plains', NULL, NULL, NULL, NULL, NULL, 'A winter cold wave affected the Terai through low temperatures, fog and disruption to daily life.', 'Cold-wave impacts can be severe for people without insulated housing or heating. Dense fog also reduces road and aviation visibility. District-level records are needed to separate this season from normal winter conditions.\n\nCold waves in the Terai are commonly accompanied by persistent fog, low daytime temperatures and reduced visibility. The hazard affects people living in poorly insulated homes, older adults, children, outdoor workers, people with chronic illness, livestock and winter crops. Transport and school attendance may also be disrupted even when no single dramatic incident is recorded. Because cold-related deaths and illness can be attributed to several medical causes, historical totals are frequently uncertain. Records should therefore explain the duration and geographic extent of the cold period and identify the source used for any health estimate.', 'Event-specific mortality varies', 'Cold-related illness varies', 'Low temperature and persistent fog', 'Health, transport, agriculture and livestock were affected.', NULL, NULL, NULL, 'DHM; Government of Nepal winter disaster reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(127, '2023 Nepal Cold Wave', '2023-nepal-cold-wave', 11, 'DISASTER', '2023-01-01', '2023', 'Terai and southern plains', NULL, NULL, NULL, NULL, NULL, 'Cold conditions and dense fog affected transport, schools, agriculture and vulnerable people in the Terai during 2023.', 'The 2023 winter record highlights the need for local cold-wave warnings and protection for older adults, children, outdoor workers and people in poorly heated homes. Exact health impacts vary by district and reporting method.\n\nCold waves in the Terai are commonly accompanied by persistent fog, low daytime temperatures and reduced visibility. The hazard affects people living in poorly insulated homes, older adults, children, outdoor workers, people with chronic illness, livestock and winter crops. Transport and school attendance may also be disrupted even when no single dramatic incident is recorded. Because cold-related deaths and illness can be attributed to several medical causes, historical totals are frequently uncertain. Records should therefore explain the duration and geographic extent of the cold period and identify the source used for any health estimate.', 'Event-specific mortality varies', 'Cold-related illness varies', 'Low temperature and persistent fog', 'Health, transport, crops, livestock and public services were affected.', NULL, NULL, NULL, 'DHM; Ministry of Health and Population; Government of Nepal winter reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(128, '1991 Nepal Forest Fire Season', '1991-nepal-forest-fire-season', 12, 'DISASTER', '1991-03-01', '1991', 'Hills and Terai forests', NULL, NULL, NULL, NULL, NULL, 'Dry-season fires affected forests and rural land in Nepal during the early 1990s.', 'Forest-fire reporting was less systematic before satellite monitoring. Fires were often detected through local observation, and impacts on air quality and biodiversity were rarely measured consistently. This record should be expanded with forest district archives.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Varies by incident', 'Varies by incident', 'Dry-season wildfire activity', 'Forest ecosystems, wildlife, pasture and nearby farms were affected.', NULL, NULL, NULL, 'Department of Forests and Soil Conservation; historical district records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(129, '2000 Nepal Forest Fire Season', '2000-nepal-forest-fire-season', 12, 'DISASTER', '2000-03-01', '2000', 'Hills and Terai forests', NULL, NULL, NULL, NULL, NULL, 'Dry vegetation and pre-monsoon conditions contributed to recurring forest fires across Nepal in 2000.', 'Wildfire risk increases when winter and spring rainfall is low, vegetation dries and wind spreads flames. Earlier seasons are difficult to compare because detection and reporting systems were less complete than today.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Varies by incident', 'Varies by incident', 'Dry-season wildfire activity', 'Forests, biodiversity, air quality and nearby settlements were exposed.', NULL, NULL, NULL, 'Department of Forests and Soil Conservation; FAO; historical district records', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(130, '2010 Nepal Forest Fire Season', '2010-nepal-forest-fire-season', 12, 'DISASTER', '2010-03-01', '2010', 'Multiple districts across Nepal', NULL, NULL, NULL, NULL, NULL, 'Forest fires during the 2010 dry season affected forests, smoke levels and rural communities.', 'The 2010 season is included as a national wildfire record because fires occurred across multiple districts. Exact burned-area estimates depend on the detection method and should be checked against satellite products and forest inventories.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Varies by incident', 'Varies by incident', 'Widespread dry-season fires', 'Forests, air quality, wildlife habitat and local livelihoods were affected.', NULL, NULL, NULL, 'Department of Forests and Soil Conservation; ICIMOD; NASA FIRMS', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(131, '2024 Nepal Wildfire Season', '2024-nepal-wildfire-season', 12, 'DISASTER', '2024-03-01', '2024', 'Multiple districts across Nepal', NULL, NULL, NULL, NULL, NULL, 'The 2024 dry season brought recurring wildfires, smoke and air-quality concerns across Nepal.', 'Wildfire activity before the monsoon can affect forests and communities over a wide area. Satellite fire detections show activity but do not by themselves establish burned area, cause or human loss; those details require ground verification.\n\nWildfires in Nepal are most frequent during the dry period before the summer monsoon, when grasses, leaf litter and forest vegetation become flammable and wind can carry fire across slopes. Ignition may be accidental, agricultural or deliberate, and a satellite hotspot does not by itself prove the size, cause or severity of a ground fire. Smoke can affect distant towns and people with respiratory conditions even when flames remain far from settlements. A detailed archive entry should separate detected fire points, burned area, forest type, damage to homes or livelihoods, injuries, deaths and the effectiveness of suppression or community response.', 'Varies by incident', 'Varies by incident', 'Widespread dry-season wildfire activity', 'Forest ecosystems, air quality, biodiversity and nearby settlements were affected.', NULL, NULL, NULL, 'ICIMOD; NASA FIRMS; Department of Forests and Soil Conservation; DHM', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(132, '1982 Nepal Debris-Flow Events', '1982-nepal-debris-flow-events', 13, 'DISASTER', '1982-07-01', '1982', 'Hill valleys and mountain roads', NULL, NULL, NULL, NULL, NULL, 'Debris flows repeatedly affected steep valleys during intense monsoon rainfall in the early 1980s.', 'Debris flows combine water, soil, rock and vegetation and can move faster than ordinary landslides. Historical national summaries often grouped them with floods or landslides, so this archive entry preserves the cross-category hazard without assigning unsupported totals.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Not reliably established', 'Not reliably established', 'Rainfall-triggered debris flow', 'River corridors, roads, bridges, homes and farmland were exposed.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; Department of Water Induced Disaster Management', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(133, '1999 Nepal Wind and Rain Disasters', '1999-nepal-wind-and-rain-disasters', 13, 'DISASTER', '1999-07-01', '1999', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Combined wind, intense rain and localized flooding affected communities across Nepal in 1999.', 'Some disaster reports record compound weather events under broad categories such as storm, flood or other disaster. This entry is retained for search and historical discovery while district-level source records are reviewed.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Incident totals vary', 'Incident totals vary', 'Compound severe-weather event', 'Roofs, crops, drainage systems, homes and local roads were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; district administration reports', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(134, '2005 Nepal Multi-Hazard Monsoon Events', '2005-nepal-multi-hazard-monsoon-events', 13, 'DISASTER', '2005-07-01', '2005', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'The 2005 monsoon produced a combination of floods, landslides, debris flows and severe storms.', 'Monsoon disaster seasons are not single hazards. Rainfall can trigger flooding in the plains, slope failure in the hills and debris flows in narrow valleys at the same time. This grouped record should be read with the individual hazard entries.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Season total varies by source', 'Many reported or displaced', 'Compound monsoon hazard', 'Homes, farmland, roads, bridges and local services were affected.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(135, '2013 Nepal Multi-Hazard Monsoon Events', '2013-nepal-multi-hazard-monsoon-events', 13, 'DISASTER', '2013-07-01', '2013', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'The 2013 monsoon produced interacting floods, landslides, lightning and severe storms across Nepal.', 'A national archive benefits from recording compound seasons because the same rainfall system can create different impacts in different terrain. Precise totals should be taken from annual government reporting and not inferred from this grouped story.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Season total varies by source', 'Many reported or displaced', 'Compound monsoon hazard', 'River flooding, slope failures, road blockages, crop losses and service disruption occurred.', NULL, NULL, NULL, 'Government of Nepal disaster-risk profile; DHM; NDRRMA', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(136, '2018 Nepal Multi-Hazard Monsoon Events', '2018-nepal-multi-hazard-monsoon-events', 13, 'DISASTER', '2018-07-01', '2018', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Floods, landslides, lightning and severe storms occurred across Nepal during the 2018 monsoon.', 'The 2018 season illustrates why disaster records should link weather, terrain and exposure. Different districts experienced different combinations of hazards, and national totals changed as new incidents were reported.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Season total varies by official reporting period', 'Many reported or displaced', 'Compound monsoon hazard', 'Transport, settlements, agriculture, hydropower and local services were affected.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; Nepal Disaster Risk Reduction Portal', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(137, '2021 Nepal Compound Disaster Season', '2021-nepal-compound-disaster-season', 13, 'DISASTER', '2021-06-01', '2021', 'Multiple districts', NULL, NULL, NULL, NULL, NULL, 'Nepal experienced earthquakes, floods, debris flows, landslides, fires and severe weather during 2021.', 'The 2021 archive record includes several hazard types rather than one event. Compound and consecutive disasters can stretch emergency capacity, damage the same infrastructure repeatedly and make recovery more difficult. Individual stories should remain the authoritative source for each incident.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Season total varies by hazard and source', 'Many reported or displaced', 'Multiple hazards', 'Housing, roads, bridges, water systems, farms and public services were affected.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; ICIMOD; sector assessments', 0, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(138, '2024 Nepal Compound Monsoon Disaster', '2024-nepal-compound-monsoon-disaster', 13, 'DISASTER', '2024-09-27', '2024', 'Central and eastern Nepal', NULL, NULL, NULL, NULL, NULL, 'Late September 2024 combined extreme rainfall, river flooding, landslides and transport disruption.', 'The 2024 disaster period shows how one extreme rainfall episode can affect urban valleys, hill roads and lowland rivers at the same time. Early reports were provisional; final figures should follow the consolidated Government of Nepal assessment and distinguish deaths, missing people and displaced households.\n\nNatural disasters in Nepal are shaped by the country\'s extreme geographic range, from the high Himalaya through steep middle hills to the densely settled Terai. A single season may involve several hazards at once, and the consequences depend on exposure, poverty, infrastructure quality, warning coverage, governance and access to emergency services. Historical records are strongest when they clearly separate observed facts, estimates, preliminary reports and later revisions. This article should therefore be updated with dated government assessments, technical studies and local evidence while preserving the uncertainty attached to older or incomplete records.', 'Official totals vary by assessment date', 'Hundreds reported in the wider disaster period', 'Compound extreme-rainfall event', 'Homes, roads, bridges, farms, schools and public infrastructure were damaged.', NULL, NULL, NULL, 'Government of Nepal/NDRRMA; DHM; UN and World Bank assessments', 1, 'PUBLISHED', NULL, NULL, NULL, NULL, '2026-09-10 04:03:31', '2026-09-10 05:18:40'),
(629, 'village', 'village-5', NULL, 'HUMAN', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A village in Nepal after a powerful earthquake — cracked and partially collapsed houses, broken roads, scattered bricks, dust in the air, damaged stone walls, people gathered outside their homes, mountains faintly visibl', 'A village in Nepal after a powerful earthquake — cracked and partially collapsed houses, broken roads, scattered bricks, dust in the air, damaged stone walls, people gathered outside their homes, mountains faintly visible in the distance, cloudy natural light, realistic documentary photography style.', NULL, NULL, NULL, NULL, 'Anonymous', NULL, NULL, NULL, 0, 'PUBLISHED', NULL, NULL, 1, 1, '2026-10-03 04:19:22', '2026-10-03 04:19:22'),
(630, 'landslide', 'landslide-7', NULL, 'HUMAN', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'i stuck i landslide last night', 'i stuck i landslide last night', NULL, NULL, NULL, NULL, 'Anonymous', NULL, NULL, NULL, 0, 'PUBLISHED', NULL, NULL, 1, 1, '2026-10-03 04:28:25', '2026-10-03 04:28:25');

